# ---------------------------------------------------------------------------
# Auto-dismiss Revit's native pop-up dialogs during export.
#
# Revit shows informational dialogs mid-export that block the thread until
# the user clicks OK — e.g. the "Printing raster images..." warning when
# exporting sheets that contain raster content. For unattended / walk-away
# exports (especially Scheduled Export) these are fatal: the export hangs
# until someone clicks the dialog, and no error is raised.
#
# UIApplication.DialogBoxShowing fires BEFORE the dialog is shown and lets
# us dismiss it programmatically. We subscribe before the export loop and
# unsubscribe after, so normal interactive dialogs (our own TaskDialogs,
# pick-folder, etc.) are never suppressed.
#
# The handler auto-dismisses by calling OverrideResult() with the standard
# OK / Close result ID. Revit's own dialog result IDs:
#   1  = OK / Yes
#   2  = Cancel / No
#   3  = Close (applies to some info-only dialogs)
#   4  = Retry
#   5  = Ignore
# We always pick 1 (OK) for informational dialogs; this is the equivalent
# of the user clicking OK to acknowledge and proceed.
#
# Safety: only auto-dismiss dialogs whose message text matches a known set
# of export-related Revit warnings. Anything unexpected (e.g. a genuine
# "save your work?" prompt from a different subsystem) is left alone so
# Revit's own logic handles it — the user is notified via the on-screen
# dialog as usual.
# ---------------------------------------------------------------------------
# Known dialog substrings that Revit shows mid-export. Matched case-
# insensitively against DialogBoxShowingEventArgs.Message (the full text
# Revit is about to display). Add new patterns here as users report them.
_EXPORT_AUTO_DISMISS_PATTERNS = [
    "raster",               # "Printing raster images..." / raster processing
    "export completed",     # informational "export completed successfully"
    "print setup",          # occasional print-setup confirmation
    "cannot be hidden",     # "some elements cannot be hidden in this view"
    "has been exported",    # "<filename> has been exported"
]

_auto_dismiss_active = [False]   # mutable flag; list so nested fn can write

def _on_dialog_showing(sender, args):
    """Auto-dismiss known Revit export dialogs. Called by the
    UIApplication.DialogBoxShowing event during the export loop."""
    if not _auto_dismiss_active[0]:
        return
    try:
        msg = ""
        try:
            msg = args.Message or ""
        except Exception:
            pass
        if not msg:
            # Some dialog types (e.g. TaskDialog-based) expose no .Message;
            # try the legacy .DialogId / .HelpId as a secondary signal.
            try:
                msg = str(args.DialogId) if hasattr(args, "DialogId") else ""
            except Exception:
                pass
        msg_lower = msg.lower()
        for pattern in _EXPORT_AUTO_DISMISS_PATTERNS:
            if pattern in msg_lower:
                try:
                    args.OverrideResult(1)   # 1 = OK
                except Exception:
                    pass
                return
    except Exception:
        pass   # never let the handler itself crash Revit


def _subscribe_auto_dismiss():
    """Start auto-dismissing known Revit dialogs. Call before the export loop."""
    try:
        import framework
        uiapp = __revit__   # UIApplication
        uiapp.DialogBoxShowing += framework.EventHandler[DialogBoxShowingEventArgs](_on_dialog_showing)
        _auto_dismiss_active[0] = True
    except Exception:
        # If subscription fails (unusual), the export still works — the user
        # just has to click through dialogs manually, same as before this fix.
        pass


def _unsubscribe_auto_dismiss():
    """Stop auto-dismissing. Call after the export loop completes."""
    _auto_dismiss_active[0] = False
    try:
        import framework
        uiapp = __revit__
        uiapp.DialogBoxShowing -= framework.EventHandler[DialogBoxShowingEventArgs](_on_dialog_showing)
    except Exception:
        pass
