# ---------------------------------------------------------------------------
# Open-path timing (diagnostic). Flip _OPEN_PERF = True to log per-stage
# timings for the dialog-open path to
#   %TEMP%\kidzink_sheet_export_open_perf.log
# Off by default — the marks are no-ops, so there is zero overhead when off.
# Use it to confirm open time and pinpoint any remaining hotspot.
# ---------------------------------------------------------------------------
_OPEN_PERF = False
_open_perf_t0 = time.time()
_open_perf_marks = []

def _perf(label):
    if _OPEN_PERF:
        _open_perf_marks.append((label, time.time()))

def _perf_dump():
    if not _OPEN_PERF or not _open_perf_marks:
        return
    try:
        lines = ["Kidzink Sheet Export - open-path timing"]
        prev = _open_perf_t0
        for _label, _t in _open_perf_marks:
            lines.append("  {:<26} +{:5.2f}s   (t={:5.2f}s)".format(
                _label, _t - prev, _t - _open_perf_t0))
            prev = _t
        lines.append("  {:<26}  TOTAL {:5.2f}s".format(
            "", _open_perf_marks[-1][1] - _open_perf_t0))
        with open(os.path.join(tempfile.gettempdir(),
                               "kidzink_sheet_export_open_perf.log"), "w") as _pf:
            _pf.write("\n".join(lines) + "\n")
    except Exception:
        pass

# ---------------------------------------------------------------------------
# Naming convention — driven entirely by the schedule column order AND the
# user's chosen profile. No parameter names or separator characters are
# hardcoded anywhere in this file: which columns appear, what order they're
# in, and what character (if any) sits between each pair, are all read from
# the wizard's saved profile ("params" + "separators", one saved per gap —
# see build_filename_from_params() below). This includes Sheet Name/Sheet
# Number — there is no special-cased rule forcing either of them to always
# use "_" or "-"; whatever the user configured in Filename Configuration is
# exactly what gets used.
# ---------------------------------------------------------------------------

ILLEGAL_CHARS = r'\/:*?"<>|'

# ---------------------------------------------------------------------------
# Helper: sanitise a string for use as a filename segment
# ---------------------------------------------------------------------------
def sanitise(value):
    if not value:
        return ""
    for ch in ILLEGAL_CHARS:
        value = value.replace(ch, "_")
    return value.strip()


# ---------------------------------------------------------------------------
# Helper: read a shared/project parameter from a sheet by name string
# ---------------------------------------------------------------------------
def get_sp(sheet, name):
    p = sheet.LookupParameter(name)
    if p and p.HasValue:
        raw = p.AsString()
        return sanitise(raw) if raw else ""
    return ""


# ---------------------------------------------------------------------------
# Helper: get current revision number string from a sheet
# ---------------------------------------------------------------------------
def get_current_revision(sheet):
    # Read SHEET_CURRENT_REVISION directly as a string parameter on the sheet.
    # This is more reliable than GetCurrentRevision() + element lookup, which
    # requires a revision cloud to be present on the sheet.
    p = sheet.get_Parameter(BuiltInParameter.SHEET_CURRENT_REVISION)
    if p and p.HasValue:
        val = p.AsString()
        if val:
            return sanitise(val)
    return ""


# ---------------------------------------------------------------------------
# Helper: read the visible fields from a schedule in column order.
# Returns a list of dicts:
#   {"name": display_name, "is_sheet_name": bool, "is_revision": bool}
# Hidden fields are excluded — they are used for filter/sort only.
# Sheet Number and Sheet Name are detected by BuiltInParameter ID.
# Current Revision is detected by BuiltInParameter.SHEET_CURRENT_REVISION.
# ---------------------------------------------------------------------------
# Detect the Sheet Collection BIP safely — it exists in 2026 but not 2025.
# We resolve it once at module level and store None if unavailable.
try:
    _SHEET_COLLECTION_BIP_ID = ElementId(BuiltInParameter.SHEET_COLLECTION_SET_NAME)
except AttributeError:
    _SHEET_COLLECTION_BIP_ID = None



