import re
import json as _json
from Autodesk.Revit.DB import StorageType

# ---------------------------------------------------------------------------
# Helper: sanitise a parameter name into a WPF-safe control Name.
# WPF Name must match [A-Za-z_][A-Za-z0-9_]* — no spaces or special chars.
# Used as the rpw CheckBox key so form.values can harvest it reliably.
# ---------------------------------------------------------------------------
def _param_key(name):
    """Return a WPF-safe key for a parameter display name."""
    key = re.sub(r"[^A-Za-z0-9_]", "_", name)
    if key and key[0].isdigit():
        key = "_" + key
    return "p__" + key


# ---------------------------------------------------------------------------
# Helper: collect all schedulable sheet parameters from the first ViewSheet.
# Returns a list of dicts suitable for the filename config dialog and
# build_filename_from_params(). Falls back gracefully if no sheets exist.
#
# Each dict: {name, key, bip, is_sheet_num, is_sheet_name, is_revision, is_sheet_collection}
# key is the WPF-safe CheckBox name (from _param_key()).
# bip is the BuiltInParameter int id or None for shared/project params.
# ---------------------------------------------------------------------------
def get_all_sheet_params(sample_sheet):
    """
    Read every schedulable parameter on a ViewSheet. Used to populate the
    filename config dialog so the user can tick which params to include.
    Returns a list ordered: Sheet Number first, then Sheet Name, then others
    alphabetically, Revision last.
    """
    result = []
    seen_names = set()

    # Fixed built-in params we always want, in preferred order
    _BIP_ORDER = [
        ("Sheet Number",   BuiltInParameter.SHEET_NUMBER,           True,  False, False, False),
        ("Sheet Name",     BuiltInParameter.SHEET_NAME,             False, True,  False, False),
        ("Current Revision", BuiltInParameter.SHEET_CURRENT_REVISION, False, False, True,  False),
    ]

    for display, bip, is_num, is_name, is_rev, is_sc in _BIP_ORDER:
        try:
            p = sample_sheet.get_Parameter(bip)
            if p is not None:
                result.append({
                    "name":                display,
                    "key":                 _param_key(display),
                    "bip":                 int(bip),
                    "is_sheet_num":        is_num,
                    "is_sheet_name":       is_name,
                    "is_revision":         is_rev,
                    "is_sheet_collection": is_sc,
                })
                seen_names.add(display)
        except Exception:
            pass

    # All other parameters on the sheet (shared/project params)
    try:
        extras = []
        for p in sample_sheet.Parameters:
            try:
                defn = p.Definition
                nm   = defn.Name.strip()
                if not nm or nm in seen_names:
                    continue
                # Only include text/integer/number storage types meaningful for filenames
                if p.StorageType not in (StorageType.String, StorageType.Integer,
                                         StorageType.Double):
                    continue
                extras.append(nm)
                seen_names.add(nm)
            except Exception:
                continue
        for nm in sorted(extras):
            result.append({
                "name":                nm,
                "key":                 _param_key(nm),
                "bip":                 None,
                "is_sheet_num":        False,
                "is_sheet_name":       False,
                "is_revision":         False,
                "is_sheet_collection": False,
            })
    except Exception:
        pass

    return result

# ---------------------------------------------------------------------------
# Helper: read a parameter value from a sheet for filename purposes.
# Handles BIP-backed and name-backed parameters uniformly.
# ---------------------------------------------------------------------------
def get_param_value(sheet, param_field):
    try:
        if param_field["bip"] is not None:
            if param_field["is_sheet_num"]:
                return sanitise(sheet.SheetNumber)
            if param_field["is_sheet_name"]:
                return sanitise(sheet.Name)
            if param_field["is_revision"]:
                return get_current_revision(sheet)
            p = sheet.get_Parameter(BuiltInParameter(param_field["bip"]))
            if p and p.HasValue:
                val = p.AsString()
                return sanitise(val) if val else ""
        else:
            return get_sp(sheet, param_field["name"])
    except Exception:
        pass
    return ""

# ---------------------------------------------------------------------------
# Helper: build filename from user-chosen params + PER-GAP separators.
# param_fields: ordered list of param dicts (only the ones user checked).
# separators: list, one entry per gap between consecutive params — fully
# user-controlled via Filename Configuration, nothing hardcoded by field type.
# ---------------------------------------------------------------------------
def build_filename_from_params(sheet, param_fields, separators):
    """Build export filename by joining param values with per-gap separators.
    separators[i] sits between param_fields[i] and param_fields[i+1].
    Falls back to "-" for any gap without an explicit separator.
    """
    tokens = []
    for pf in param_fields:
        val = get_param_value(sheet, pf)
        tokens.append(val if val else "")
    if not any(tokens):
        return sanitise(sheet.SheetNumber) or "Sheet"
    result = tokens[0] if tokens else ""
    for _i in range(1, len(tokens)):
        _sep = separators[_i - 1] if _i - 1 < len(separators) else "-"
        # "(none)" is the wizard's "no separator" sentinel (normally only on
        # the unused trailing gap). Treat it as empty defensively so it can
        # never leak into a filename via a loaded/hand-edited profile that
        # happens to carry it on a non-last gap.
        if _sep == "(none)":
            _sep = ""
        result += _sep + tokens[_i]
    return result

def get_collection_name(sheet):
    """Return the Sheet Collection name for a sheet, or _NoSheetCollection."""
    try:
        coll_id = sheet.SheetCollectionId
        if coll_id == ElementId.InvalidElementId:
            return "_NoSheetCollection"
        coll_elem = doc.GetElement(coll_id)
        name = sanitise(coll_elem.Name) if coll_elem else ""
        return name if name else "_NoSheetCollection"
    except Exception:
        return "_NoSheetCollection"


_CREATED_DIRS_CACHE = set()

def get_output_path(sheet, output_root, fmt, project_has_collections,
                    folder_mode="Type > Sheet Collection"):
    """Return the full folder path for a sheet export.
    fmt is 'PDF' or 'DWG'.

    folder_mode:
      'Type > Sheet Collection'   -> root/PDF/CollectionName/
      'Sheet Collection > Type'   -> root/CollectionName/PDF/
    """
    if not project_has_collections:
        # No collections in project — flat: root\PDF\ or root\DWG\
        folder = os.path.join(output_root, fmt)
    else:
        coll_name = get_collection_name(sheet)
        if folder_mode == "Sheet Collection > Type":
            folder = os.path.join(output_root, coll_name, fmt)
        else:
            # Default: Type > Sheet Collection
            folder = os.path.join(output_root, fmt, coll_name)

    if folder not in _CREATED_DIRS_CACHE:
        if not os.path.exists(folder):
            os.makedirs(folder)
        _CREATED_DIRS_CACHE.add(folder)
    return folder


# ---------------------------------------------------------------------------
# Speed: FilteredElementCollector(doc).OfClass(ViewSheet) re-scans every
# element in the model. This script previously called it independently in
# get_sheets_from_schedule(), get_all_model_sheets(), and twice more for
# param-seeding (interactive + headless paths) — up to 4 full model scans
# per run, and get_sheets_from_schedule() re-runs it every time the user
# changes the schedule dropdown in the wizard. Cache it once per script
# execution (module-level, cleared on each fresh script.py run).
# ---------------------------------------------------------------------------
_ALL_SHEETS_CACHE = None

def _get_all_view_sheets():
    global _ALL_SHEETS_CACHE
    if _ALL_SHEETS_CACHE is None:
        _ALL_SHEETS_CACHE = list(
            FilteredElementCollector(doc).OfClass(ViewSheet).ToElements())
    return _ALL_SHEETS_CACHE


# ---------------------------------------------------------------------------
# Helper: collect all sheet-list schedules in the document
# ---------------------------------------------------------------------------
def get_sheet_schedules():
    schedules = FilteredElementCollector(doc)\
        .OfClass(ViewSchedule)\
        .ToElements()
    sheet_cat_id = ElementId(BuiltInCategory.OST_Sheets)
    return [s for s in schedules
            if s.Definition.CategoryId == sheet_cat_id
            and not s.IsTemplate]


# ---------------------------------------------------------------------------
# Helper: read sheets from a ViewSchedule in row order
# ---------------------------------------------------------------------------
def get_sheets_from_schedule(schedule):
    """Read sheets from a ViewSchedule in row order.
    Returns a list of ViewSheet objects.
    """
    all_sheets = _get_all_view_sheets()
    sheet_map = {s.SheetNumber: s for s in all_sheets}
    sheet_name_map = {}
    for s in all_sheets:
        nm = s.Name
        if nm and nm not in sheet_name_map:
            sheet_name_map[nm] = s

    defn        = schedule.Definition
    field_order = defn.GetFieldOrder()
    match_col   = None
    match_map   = None
    visible_index = 0
    for fid in field_order:
        field = defn.GetField(fid)
        if field.IsHidden:
            continue
        try:
            bip_id = field.GetSchedulableField().ParameterId
        except Exception:
            bip_id = None
        if bip_id is not None:
            if bip_id == ElementId(BuiltInParameter.SHEET_NUMBER):
                match_col = visible_index
                match_map = sheet_map
            elif match_col is None and bip_id == ElementId(BuiltInParameter.SHEET_NAME):
                match_col = visible_index
                match_map = sheet_name_map
        visible_index += 1

    if match_col is None:
        elements = FilteredElementCollector(doc, schedule.Id)\
            .OfClass(ViewSheet).ToElements()
        seen, unique = set(), []
        for s in elements:
            if s.Id.Value not in seen:
                seen.add(s.Id.Value)
                unique.append(s)
        return unique

    table   = schedule.GetTableData()
    section = table.GetSectionData(SectionType.Body)
    n_rows  = section.NumberOfRows
    result  = []
    seen    = set()
    for row in range(n_rows):
        cell = schedule.GetCellText(SectionType.Body, row, match_col)
        if cell and cell in match_map:
            s = match_map[cell]
            if s.Id.Value not in seen:
                seen.add(s.Id.Value)
                result.append(s)
    return result


# ---------------------------------------------------------------------------
# Helper: collect every real (non-placeholder) sheet in the model, sorted by
# sheet number. Used by the Sheet Source step's "By Selection" sub-mode —
# the user ticks whichever sheets they want directly, no schedule involved.
# ---------------------------------------------------------------------------
def get_all_model_sheets():
    all_sheets = _get_all_view_sheets()
    real_sheets = []
    for s in all_sheets:
        try:
            if s.IsPlaceholder:
                continue
        except Exception:
            pass
        real_sheets.append(s)

    def _sort_key(s):
        num = s.SheetNumber or ""
        # Natural-ish sort: split into digit/non-digit runs so "A2" < "A10".
        parts = re.split(r'(\d+)', num)
        return [int(p) if p.isdigit() else p.lower() for p in parts]

    real_sheets.sort(key=_sort_key)
    return real_sheets


# ---------------------------------------------------------------------------
# Helper: collect every Revit link instance in the model, resolving a
# display path for each (falling back to a clear "not found" marker for
# unresolved/missing links rather than raising).
# ---------------------------------------------------------------------------
def get_all_links():
    link_instances = FilteredElementCollector(doc).OfClass(RevitLinkInstance).ToElements()
    result = []
    seen_type_ids = set()
    for li in link_instances:
        try:
            link_type = doc.GetElement(li.GetTypeId())
        except Exception:
            link_type = None
        if link_type is None:
            continue
        # Multiple instances can share the same link type (same file linked
        # more than once) — de-dupe by type so each real link file appears
        # once in the checklist, matching what "Reload Links" actually reloads.
        tid = link_type.Id.Value if hasattr(link_type.Id, "Value") else link_type.Id.IntegerValue
        if tid in seen_type_ids:
            continue
        seen_type_ids.add(tid)

        try:
            name = Element.Name.__get__(link_type)
        except Exception:
            # Fallback for older/odd builds where the descriptor trick itself
            # fails — try the plain attribute, else fall back to an id-based
            # placeholder rather than crashing the whole collection.
            try:
                name = link_type.Name
            except Exception:
                name = "(unnamed link {})".format(tid)
        path_display = "(path not found)"
        try:
            ext_ref = link_type.GetExternalFileReference()
            if ext_ref is not None:
                model_path = ext_ref.GetPath()
                path_display = ModelPathUtils.ConvertModelPathToUserVisiblePath(model_path)
        except Exception:
            pass

        result.append({"name": name, "path_display": path_display, "link_type": link_type})

    result.sort(key=lambda r: r["name"].lower())
    return result


def reload_selected_links(link_names):
    """Reload each named link. Returns (succeeded_names, failed_pairs) where
    failed_pairs is a list of (name, error_message)."""
    succeeded = []
    failed = []
    all_links = get_all_links()
    by_name = {l["name"]: l["link_type"] for l in all_links}
    for name in link_names:
        link_type = by_name.get(name)
        if link_type is None:
            failed.append((name, "Link not found in the current document"))
            continue
        try:
            result = link_type.Reload()
            # LinkLoadResultType.LinkLoaded / ... — treat anything that
            # doesn't come back as an outright failure as success, since
            # exact enum members vary slightly across Revit versions.
            status = str(result.LoadResult) if hasattr(result, "LoadResult") else "Unknown"
            if "Fail" in status or "NotFound" in status or "Invalid" in status:
                failed.append((name, status))
            else:
                succeeded.append(name)
        except Exception as ex:
            failed.append((name, str(ex)))
    return succeeded, failed


def sync_with_central():
    """Synchronize the current document with central. Returns (True, None)
    on success, or (False, error_message) on failure — never raises, so the
    caller can decide whether to proceed with the export anyway."""
    try:
        if not doc.IsWorkshared:
            return False, "Document is not workshared."
        transact_opts = TransactWithCentralOptions()
        sync_opts = SynchronizeWithCentralOptions()
        relinquish_opts = RelinquishOptions(True)
        sync_opts.SetRelinquishOptions(relinquish_opts)
        sync_opts.Comment = "Kidzink Sheet Export - auto-sync before export"
        doc.SynchronizeWithCentral(transact_opts, sync_opts)
        return True, None
    except Exception as ex:
        return False, str(ex)


# ---------------------------------------------------------------------------
# Helper: get PDF export options
# CRITICAL: PaperPlacement MUST be Center when PaperFormat is Default.
# Any other value causes doc.Export() to silently return False.
#
# quality: "Low (72 DPI)" | "Medium (150 DPI)" | "High (300 DPI)"
#
# NOTE: PDFExportQualityType.DPI150 was introduced in Revit 2024 and does
# not exist on older installs. We probe the enum at runtime so the script
# works on any Revit version without modification.
# ---------------------------------------------------------------------------
def _safe_quality(name, fallback):
    """Return PDFExportQualityType.<name> if it exists, else <fallback>."""
    try:
        return getattr(PDFExportQualityType, name)
    except AttributeError:
        return fallback


def get_pdf_options(quality="High (300 DPI)", processing="Vector",
                    hide_crop=True, hide_ref=True,
                    hide_scope=True, hide_view_tags=True):
    opts = PDFExportOptions()
    opts.Combine          = False
    opts.PaperFormat      = ExportPaperFormat.Default
    opts.PaperPlacement   = PaperPlacementType.Center   # REQUIRED
    opts.AlwaysUseRaster  = (processing == "Raster")

    # Pinned OFF, not user-configurable. A live test (2026-07-21) with
    # background export enabled produced a genuine Revit-side crash — the
    # native background-export worker process crashed outright (see
    # journal.*.worker2.log / worker2.*.dmp, "PDF Export ... failed" dialog).
    # Revit also reports doc.Export() as succeeded the instant the job is
    # *handed off* to the worker, before the file exists — which breaks this
    # tool's "scan the temp folder right after Export() returns" pattern even
    # on a run where the worker doesn't crash. Both issues are on Revit's
    # side, not fixable from pyRevit, so this stays hardcoded rather than
    # exposed as a setting. SetExportInBackground() only exists on RevitAPI
    # 25.0+ (Revit 2025+), hence the guard.
    try:
        opts.SetExportInBackground(False)
    except AttributeError:
        pass

    if quality == "Low (72 DPI)":
        opts.RasterQuality = RasterQualityType.Low
        opts.ExportQuality = _safe_quality("DPI72", PDFExportQualityType.DPI300)
    elif quality == "Medium (150 DPI)":
        opts.RasterQuality = RasterQualityType.Medium
        opts.ExportQuality = _safe_quality("DPI150", PDFExportQualityType.DPI300)
    elif quality == "Very High (600 DPI)":
        opts.RasterQuality = RasterQualityType.Presentation
        opts.ExportQuality = _safe_quality("DPI600", PDFExportQualityType.DPI300)
    else:
        # High (300 DPI) — default
        opts.RasterQuality = RasterQualityType.Presentation
        opts.ExportQuality = PDFExportQualityType.DPI300

    opts.HideCropBoundaries       = hide_crop
    opts.HideReferencePlane       = hide_ref
    opts.HideScopeBoxes           = hide_scope
    opts.HideUnreferencedViewTags = hide_view_tags
    return opts


# ---------------------------------------------------------------------------
# Helper: get DWG export options
#
# Priority:
#   1. If a saved setup exists in the project → load it (respects BIM manager
#      layer mapping, patterns, fonts) then override FileVersion + MergedViews.
#   2. If no saved setup → build from scratch using AIA + R2018 defaults.
#      Nothing is written back to the model — all options are transient.
#
# Called ONCE before the export loop, not per sheet.
# ---------------------------------------------------------------------------
def _eid_int(eid):
    """Bidirectional ElementId -> int accessor: .Value (Revit 2026+) falls
    back to .IntegerValue (Revit 2025). Used as a stable dict key instead of
    the element/sheet object itself — Revit API objects can be re-wrapped by
    IronPython between calls, so relying on their default .NET hash/equality
    for dict lookups isn't guaranteed stable; an ElementId's integer value is."""
    try:
        return eid.Value
    except AttributeError:
        return eid.IntegerValue


# ---------------------------------------------------------------------------
# DWG version map — built ONCE at module level (probed from ACADVersion enum)
# ---------------------------------------------------------------------------
_DWG_VERSION_MAP = {}
for _vname in ["R2018", "R2013", "R2010", "R2007", "R2004", "R2000"]:
    try:
        _DWG_VERSION_MAP[_vname] = getattr(ACADVersion, _vname)
    except AttributeError:
        pass
_dwg_ver_opts_global = sorted(_DWG_VERSION_MAP.keys(), reverse=True)

# ---------------------------------------------------------------------------
# Short-path temp directory for Revit exports.
# Revit appends the full sheet title to the export prefix, and the default
# %TEMP% path (C:\Users\<long_username>\AppData\Local\Temp\) plus a long
# sheet name easily exceeds Windows' 260-character MAX_PATH limit, causing
# "Can't create <file>" errors. Using a short root (C:\Temp\kzk) gives
# Revit ~220 extra characters for its auto-generated filenames.
# ---------------------------------------------------------------------------
def _short_tmpdir(prefix="es_"):
    _short_root = os.path.join(os.environ.get("SystemDrive", "C:") + os.sep,
                               "Temp", "kzk")
    try:
        if not os.path.isdir(_short_root):
            os.makedirs(_short_root)
        return tempfile.mkdtemp(prefix=prefix, dir=_short_root)
    except Exception:
        return tempfile.mkdtemp(prefix=prefix)


# ---------------------------------------------------------------------------
# Deferred temp-directory cleanup. shutil.rmtree() is synchronous I/O that
# can take 0.5-3s per directory on network/OneDrive paths (Windows Defender
# scanning). Moving ALL cleanup to a single post-session pass keeps it off
# the per-sheet critical path — the user sees the output folder open
# immediately, and cleanup runs while they're browsing files.
# ---------------------------------------------------------------------------
_CLEANUP_DIRS = []

def _queue_cleanup(path):
    """Queue a temp directory for removal at session end."""
    if path:
        _CLEANUP_DIRS.append(path)

def _flush_cleanup():
    """Remove all queued temp directories. Call once after the session."""
    for d in _CLEANUP_DIRS:
        try:
            shutil.rmtree(d, ignore_errors=True)
        except Exception:
            pass
    _CLEANUP_DIRS[:] = []


def _safe_set(obj, prop_name, value):
    """Set obj.prop_name = value, silently skipping if the property doesn't
    exist on this Revit build. DXFExportOptions nominally inherits from
    DWGExportOptions, but some properties (e.g. MergedViews — DXF has no
    view-merging concept) aren't actually present on every version, so every
    export-options property is set defensively rather than assumed present."""
    try:
        setattr(obj, prop_name, value)
        return True
    except Exception:
        return False


def get_dwg_options():
    setup_names = BaseExportOptions.GetPredefinedSetupNames(doc)

    if setup_names and setup_names.Count > 0:
        # Load the first saved setup — respects whatever the BIM manager set
        opts = DWGExportOptions.GetPredefinedOptions(doc, setup_names[0])
        # Override version and merge — regardless of what the setup has
        _safe_set(opts, "FileVersion", ACADVersion.R2018)
        _safe_set(opts, "MergedViews", True)
    else:
        # No saved setup — build a sensible default in code
        # Note: pattern (.pat) and linetype (.lin) file mappings cannot be set
        # via the API — Revit will use its built-in AIA defaults for those.
        opts = DWGExportOptions()
        _safe_set(opts, "FileVersion", ACADVersion.R2018)
        _safe_set(opts, "LayerMapping", "AIA")
        _safe_set(opts, "MergedViews", True)
        _safe_set(opts, "PropOverrides", PropOverrideMode.ByLayer)
        _safe_set(opts, "LineScaling", LineScaling.PaperSpace)
        _safe_set(opts, "SharedCoords", False)
        _safe_set(opts, "ExportOfSolids", SolidGeometry.ACIS)
        _safe_set(opts, "TargetUnit", ExportUnit.Default)

    return opts


def get_dwfx_options(quality_label="Default", merged=True):
    # DWFExportOptions has no ACADVersion (it isn't an AutoCAD format) — it
    # exposes its own image-quality control. Enum member names are probed at
    # runtime rather than hardcoded (matches the pattern used for
    # PDFExportQualityType/ImageFileType elsewhere in this tool), since exact
    # names can vary across Revit builds.
    #
    # merged=True only makes sense when every sheet in the ViewSet passed to
    # doc.Export() should collapse into ONE combined file (the "DWFx
    # Combined" mode). It must be False whenever multiple sheets are passed
    # in a single call but SEPARATE output files are wanted (the per-sheet
    # batch export below) — merging a single-sheet ViewSet is a no-op either
    # way, so existing single-sheet callers are unaffected by this default.
    opts = DWFExportOptions()
    _safe_set(opts, "MergedViews", merged)

    _quality_map = {
        "Default": ["Default"],
        "Low":     ["Low"],
        "Medium":  ["Medium"],
        "High":    ["High"],
        "Best":    ["Best"],
    }
    try:
        from Autodesk.Revit.DB import DWFImageQuality
        for name in _quality_map.get(quality_label, ["Default"]):
            try:
                opts.ImageQuality = getattr(DWFImageQuality, name)
                break
            except AttributeError:
                continue
    except Exception:
        pass   # property/enum not available on this Revit build — use defaults

    try:
        from Autodesk.Revit.DB import ExportObjectVisibility
        opts.ExportObjectVisibility = getattr(
            ExportObjectVisibility, "ExportVisibleObjects",
            getattr(ExportObjectVisibility, "ExportAllObjects", None))
    except Exception:
        pass

    return opts


def get_dwf_options(quality_label="Default", merged=True):
    # Same underlying DWFExportOptions class as DWFx — Revit has no separate
    # "DWFExportOptions" class for legacy DWF. Kept as its own function
    # (not an alias of get_dwfx_options) so DWF-specific tuning can diverge
    # later without touching the DWFx path. See export_dwf() below for the
    # verification step that confirms Revit actually wrote a .dwf and not a
    # .dwfx wearing the wrong extension.
    opts = DWFExportOptions()
    _safe_set(opts, "MergedViews", merged)

    _quality_map = {
        "Default": ["Default"],
        "Low":     ["Low"],
        "Medium":  ["Medium"],
        "High":    ["High"],
        "Best":    ["Best"],
    }
    try:
        from Autodesk.Revit.DB import DWFImageQuality
        for name in _quality_map.get(quality_label, ["Default"]):
            try:
                opts.ImageQuality = getattr(DWFImageQuality, name)
                break
            except AttributeError:
                continue
    except Exception:
        pass   # property/enum not available on this Revit build — use defaults

    try:
        from Autodesk.Revit.DB import ExportObjectVisibility
        opts.ExportObjectVisibility = getattr(
            ExportObjectVisibility, "ExportVisibleObjects",
            getattr(ExportObjectVisibility, "ExportAllObjects", None))
    except Exception:
        pass

    return opts


def get_dxf_options():
    # DXFExportOptions extends DWGExportOptions in the Revit API, so the
    # same properties are expected to apply — but MergedViews specifically
    # is absent on some builds (DXF has no "views" concept in the same
    # sense), so every property is set defensively via _safe_set rather than
    # assumed present. DXF has no separate version dropdown in the wizard —
    # it shares the DWG Version setting, overridden the same way right
    # before use (see _DWG_VERSION_MAP.get(...) below).
    opts = DXFExportOptions()
    _safe_set(opts, "FileVersion", ACADVersion.R2018)
    _safe_set(opts, "LayerMapping", "AIA")
    _safe_set(opts, "MergedViews", True)
    _safe_set(opts, "PropOverrides", PropOverrideMode.ByLayer)
    _safe_set(opts, "LineScaling", LineScaling.PaperSpace)
    _safe_set(opts, "SharedCoords", False)
    _safe_set(opts, "ExportOfSolids", SolidGeometry.ACIS)
    _safe_set(opts, "TargetUnit", ExportUnit.Default)
    return opts


# ---------------------------------------------------------------------------
# PDF24 DocTool — detect installation for post-export PDF compression.
# Checks Program Files, user-local PDF24, and per-user Store installs.
# Always uses pdf24-DocTool.exe (CLI) — never pdf24-Toolbox.exe (GUI).
#
# PERF: resolution is LAZY (see _pdf24_doctool). The Microsoft-Store fallback
# walks %LOCALAPPDATA%\Programs, which can take several seconds on machines
# with many user-installed apps — that walk must never sit on the dialog-open
# path. It's only reached at export time, and only when compression is on.
# ---------------------------------------------------------------------------
def _resolve_pdf24_candidate(c):
    """Return a usable pdf24-DocTool.exe path for candidate c, or None.
    If c points at the GUI Toolbox, resolve DocTool from the same folder."""
    if not os.path.isfile(c):
        return None
    if c.lower().endswith("pdf24-toolbox.exe"):
        doctool = os.path.join(os.path.dirname(c), "pdf24-DocTool.exe")
        return doctool if os.path.isfile(doctool) else None
    return c


def _find_pdf24_doctool():
    # 1) Standard install locations first — a handful of cheap stat() calls.
    fixed = [
        r"C:\Program Files\PDF24\pdf24-Toolbox.exe",
        r"C:\Program Files\PDF24\pdf24-DocTool.exe",
        r"C:\Program Files (x86)\PDF24\pdf24-Toolbox.exe",
        r"C:\Program Files (x86)\PDF24\pdf24-DocTool.exe",
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "PDF24", "pdf24-Toolbox.exe"),
        os.path.join(os.environ.get("LOCALAPPDATA", ""), "PDF24", "pdf24-DocTool.exe"),
        os.path.join(os.environ.get("APPDATA",      ""), "PDF24", "pdf24-Toolbox.exe"),
        os.path.join(os.environ.get("APPDATA",      ""), "PDF24", "pdf24-DocTool.exe"),
        os.path.join(os.environ.get("PROGRAMFILES",  ""), "PDF24", "pdf24-Toolbox.exe"),
        os.path.join(os.environ.get("PROGRAMFILES",  ""), "PDF24", "pdf24-DocTool.exe"),
    ]
    for c in fixed:
        found = _resolve_pdf24_candidate(c)
        if found:
            return found

    # 2) Only if no standard install was found do we walk the per-user
    #    Programs tree (Microsoft Store installs). Skipped entirely whenever
    #    PDF24 is installed normally — which is the common case.
    _user_progs = os.path.join(os.environ.get("LOCALAPPDATA", ""), "Programs")
    if os.path.isdir(_user_progs):
        for _root, _dirs, _files in os.walk(_user_progs):
            for _f in _files:
                if _f.lower() in ("pdf24-toolbox.exe", "pdf24-doctool.exe"):
                    found = _resolve_pdf24_candidate(os.path.join(_root, _f))
                    if found:
                        return found
    return None


# Lazy + cached accessor. _PDF24_CACHE: [] = not yet resolved,
# [value] = resolved (value may be None if PDF24 isn't installed). Resolution
# happens on first real use (export-time compression), never at module import.
_PDF24_CACHE = []
def _pdf24_doctool():
    if not _PDF24_CACHE:
        _PDF24_CACHE.append(_find_pdf24_doctool())
    return _PDF24_CACHE[0]



# ---------------------------------------------------------------------------
# Helper: compress a PDF using pdf24-DocTool.exe -applyProfile
# Runs Ghostscript on the WHOLE file (vector, fonts, images, streams).
# profile: PDF24 CLI profile ID e.g. "default/good" (see function docstring).
# Supplying -profile on the CLI suppresses PDF24's profile-selector dialog entirely.
# Returns (True, elapsed) on success, (error_string, elapsed) on failure.
# If pdf24-DocTool.exe not found, returns True immediately (no-op).
# ---------------------------------------------------------------------------
def compress_pdf(pdf_path, profile="default/good"):
    """
    Compress a PDF using pdf24-DocTool.exe -applyProfile, which runs Ghostscript
    on the WHOLE file (vector, fonts, images, streams) — unlike -compress which
    only resamples embedded raster images. For Revit PDFs (mostly vector content)
    this produces meaningful size reduction.

    profile: PDF24 CLI profile ID — MUST include "default/" prefix, e.g.:
      "default/low"    — heavy compression, smallest file
      "default/medium" — moderate compression
      "default/good"   — good balance for architectural drawings (default)
      "default/high"   — light compression, high fidelity
      "default/best"   — minimal compression, max fidelity
    The "default/" prefix is mandatory — omitting it makes PDF24 show the
    profile-selector dialog instead of running silently.

    IronPython 2.7: communicate() has no timeout kwarg.
    Uses a manual poll/wait loop with a deadline instead.
    Returns (True, elapsed_seconds) on success, (error_string, elapsed_seconds) on failure.
    If pdf24-DocTool.exe not found, returns True immediately (no-op).
    """
    _doctool = _pdf24_doctool()
    if not _doctool:
        return True, 0.0   # no-op — tool not installed

    t0      = time.time()
    tmp_dir = _short_tmpdir("es_compress_")
    tmp_out = os.path.join(tmp_dir, "compressed.pdf")
    try:
        cmd = [
            _doctool,
            "-applyProfile",
            "-profile", profile,
            "-noProgress",
            "-outputFile", tmp_out,
            pdf_path,
        ]
        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            creationflags=0x08000000   # CREATE_NO_WINDOW
        )

        # IronPython 2.7: communicate() does not support the timeout kwarg.
        # Poll manually with a hard deadline instead.
        deadline = time.time() + 180.0   # 3-minute hard limit per file
        while proc.poll() is None:
            if time.time() > deadline:
                try:
                    proc.kill()
                except Exception:
                    pass
                return "pdf24 compress timed out (>180s)", time.time() - t0
            time.sleep(0.25)

        # Process has exited — read output
        stdout_data, stderr_data = proc.communicate()

        if proc.returncode != 0:
            err = ""
            try:
                err = stderr_data.decode("utf-8", errors="replace").strip()
            except Exception:
                pass
            return ("pdf24 compress error ({}): {}".format(
                proc.returncode, err)), time.time() - t0

        if not os.path.isfile(tmp_out):
            return "compress produced no output file", time.time() - t0

        # Replace original — remove first, then copy from isolated temp dir
        os.remove(pdf_path)
        shutil.copy2(tmp_out, pdf_path)
        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION in compress_pdf: " + str(e), time.time() - t0
    finally:
        # Always clean up the isolated temp dir
        _queue_cleanup(tmp_dir)


# ---------------------------------------------------------------------------
# Batch PDF compression — compress ALL exported PDFs in a single
# pdf24-DocTool.exe invocation instead of spawning one subprocess per file.
# Each subprocess launch + Ghostscript init carries ~2-5s of fixed overhead,
# so batching N files into 1 call saves (N-1) x that overhead.
# Falls back to per-file compression on any error so existing behaviour is
# never lost.
# ---------------------------------------------------------------------------
def compress_pdf_batch(pdf_paths, profile="default/good"):
    """Compress multiple PDFs in one pdf24-DocTool.exe invocation.
    Returns (True, elapsed_seconds) on success, or (error_string, elapsed_seconds)
    on failure. If pdf24-DocTool.exe is not installed, returns True immediately."""
    _doctool = _pdf24_doctool()
    if not _doctool or not pdf_paths:
        return True, 0.0

    t0 = time.time()
    tmp_dir = _short_tmpdir("es_compressbatch_")
    try:
        cmd = [
            _doctool,
            "-applyProfile",
            "-profile", profile,
            "-noProgress",
            "-outputDir", tmp_dir,
        ] + list(pdf_paths)

        proc = subprocess.Popen(
            cmd,
            stdout=subprocess.PIPE,
            stderr=subprocess.PIPE,
            creationflags=0x08000000   # CREATE_NO_WINDOW
        )

        # IronPython 2.7: communicate() has no timeout kwarg.
        # Poll manually with a hard deadline — generous for a full batch.
        deadline = time.time() + 600.0   # 10 min for entire batch
        while proc.poll() is None:
            if time.time() > deadline:
                try:
                    proc.kill()
                except Exception:
                    pass
                return "batch compress timed out (>600s)", time.time() - t0
            time.sleep(0.5)

        proc.communicate()

        if proc.returncode != 0:
            return "batch compress error ({})".format(proc.returncode), time.time() - t0

        # Replace each original with its compressed counterpart
        replaced = 0
        for src_path in pdf_paths:
            basename = os.path.basename(src_path)
            compressed = os.path.join(tmp_dir, basename)
            if os.path.isfile(compressed):
                try:
                    os.remove(src_path)
                    shutil.move(compressed, src_path)
                    replaced += 1
                except Exception:
                    pass   # leave original untouched

        if replaced == 0:
            return "batch compress produced no output files", time.time() - t0

        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION in compress_pdf_batch: " + str(e), time.time() - t0
    finally:
        _queue_cleanup(tmp_dir)


# ---------------------------------------------------------------------------
# Helper: format file size in bytes to human-readable string
# ---------------------------------------------------------------------------
def fmt_size(path):
    """Return file size as a readable string e.g. 1.2 MB, 450 KB."""
    try:
        b = os.path.getsize(path)
        if b >= 1024 * 1024:
            return "{:.1f} MB".format(b / (1024.0 * 1024.0))
        elif b >= 1024:
            return "{:.0f} KB".format(b / 1024.0)
        return "{} B".format(b)
    except Exception:
        return "?"


# ---------------------------------------------------------------------------
# Helper: format seconds into a readable string
# ---------------------------------------------------------------------------
def fmt_time(seconds):
    if seconds < 60:
        return "{:.1f}s".format(seconds)
    m = int(seconds) // 60
    s = seconds - (m * 60)
    return "{}m {:.1f}s".format(m, s)


# ---------------------------------------------------------------------------
# Helper: escape a data value for safe insertion into the HTML report.
# Apply ONLY to interpolated values (paths, names, error text) — never to
# the report template itself, which contains intentional entities such as
# &mdash; / &nbsp; / &copy; that must pass through untouched.
# ---------------------------------------------------------------------------
def _esc(value):
    s = value if isinstance(value, basestring) else str(value)  # noqa: F821
    return (s.replace("&", "&amp;")
             .replace("<", "&lt;")
             .replace(">", "&gt;"))


# ---------------------------------------------------------------------------
# Helper: bring Revit main window to foreground before showing a dialog.
# Prevents TaskDialog from rendering behind the pyRevit output window.
# ---------------------------------------------------------------------------
def _bring_revit_forward():
    try:
        _hwnd = __revit__.MainWindowHandle.ToInt64()
        ctypes.windll.user32.AllowSetForegroundWindow(_hwnd)
        ctypes.windll.user32.SetForegroundWindow(_hwnd)
    except Exception:
        pass


# ---------------------------------------------------------------------------
# Export one sheet to PDF
#
# IronPython overload problem: doc.Export(folder, ids, PDFExportOptions) is
# ambiguous with the SAT overload — IronPython picks the wrong one.
# Fix: use .Overloads[] with the exact .NET generic signature to force the
# correct overload. IList[ElementId] is the key discriminator.
#
# Strategy: export to temp folder, find the .pdf Revit wrote, rename it.
# Returns (True, elapsed_seconds) on success, (error_string, elapsed_seconds) on failure.
# ---------------------------------------------------------------------------
def export_pdf(sheet, export_name, output_folder, pdf_settings=None):
    pdf_settings = pdf_settings or {}
    sheet_ids = List[ElementId]([sheet.Id])
    opts      = get_pdf_options(**pdf_settings)
    t0        = time.time()

    # Force the correct overload explicitly by .NET type signature
    try:
        pdf_export = doc.Export.Overloads[str, IList[ElementId], PDFExportOptions]
    except Exception as e:
        return "Overload resolution failed: " + str(e), time.time() - t0

    tmp_dir = _short_tmpdir("es_pdf_")
    try:
        result = pdf_export(tmp_dir, sheet_ids, opts)

        # Find whatever PDF Revit wrote in temp folder
        pdf_files = [f for f in os.listdir(tmp_dir) if f.lower().endswith(".pdf")]

        if not pdf_files:
            return "doc.Export returned {} — no PDF written".format(result), time.time() - t0

        src  = os.path.join(tmp_dir, pdf_files[0])
        dest = os.path.join(output_folder, export_name + ".pdf")
        if os.path.isfile(dest):
            os.remove(dest)
        shutil.move(src, dest)
        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0
    finally:
        try:
            _queue_cleanup(tmp_dir)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Export ALL sheets to a SINGLE combined multi-page PDF.
# Uses PDFExportOptions.Combine = True — Revit merges all sheets into one
# file in sheet-set order. Filename is fixed (not per-sheet).
# ---------------------------------------------------------------------------
def export_pdf_combined(sheets, export_name, output_folder, pdf_settings=None):
    pdf_settings  = dict(pdf_settings or {})
    sheet_ids     = List[ElementId]([s.Id for s in sheets])
    opts          = get_pdf_options(**pdf_settings)
    opts.Combine  = True            # merge all sheets into one PDF
    opts.FileName = export_name     # REQUIRED when Combine=True — extension auto-appended
    t0            = time.time()

    try:
        pdf_export = doc.Export.Overloads[str, IList[ElementId], PDFExportOptions]
    except Exception as e:
        return "Overload resolution failed: " + str(e), time.time() - t0

    tmp_dir = _short_tmpdir("es_pdfcombo_")
    try:
        result = pdf_export(tmp_dir, sheet_ids, opts)
        pdf_files = [f for f in os.listdir(tmp_dir) if f.lower().endswith(".pdf")]

        if not pdf_files:
            return "doc.Export returned {} — no combined PDF written".format(result), time.time() - t0

        src  = os.path.join(tmp_dir, pdf_files[0])
        dest = os.path.join(output_folder, export_name + ".pdf")
        if os.path.isfile(dest):
            os.remove(dest)
        shutil.move(src, dest)
        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0
    finally:
        try:
            _queue_cleanup(tmp_dir)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Sidecar files Revit can write alongside a DWG/DXF export — genuine raster
# images only. Anything else left in the temp folder (e.g. a .pcp plot-
# configuration file, which Revit can generate depending on export settings)
# is junk from the output folder's perspective and gets deleted instead of
# moved out.
# ---------------------------------------------------------------------------
_DWG_SIDECAR_IMAGE_EXTS = (".png", ".jpg", ".jpeg", ".bmp", ".tif", ".tiff")


# ---------------------------------------------------------------------------
# Export one sheet to DWG
#
# doc.Export() for DWG uses fileName as a PREFIX — Revit appends its own
# sheet name/number suffix. Strategy: export to temp folder with neutral
# prefix "_tmp", find the .dwg Revit wrote, rename it to export_name.dwg.
# Returns (True, elapsed_seconds) on success, (error_string, elapsed_seconds) on failure.
# dwg_opts passed in — built once outside the loop for performance.
# ---------------------------------------------------------------------------
def export_dwg(sheet, export_name, output_folder, dwg_opts):
    sheet_ids = List[ElementId]([sheet.Id])

    t0 = time.time()
    try:
        dwg_export = doc.Export.Overloads[str, str, ICollection[ElementId], DWGExportOptions]
    except Exception as e:
        return "Overload resolution failed: " + str(e), time.time() - t0

    tmp_dir = _short_tmpdir("es_dwg_")
    try:
        result = dwg_export(tmp_dir, "_tmp", sheet_ids, dwg_opts)

        dwg_files = [f for f in os.listdir(tmp_dir)
                     if f.lower().endswith(".dwg")]

        if not dwg_files:
            return "doc.Export succeeded={} but no .dwg found in temp folder".format(result), time.time() - t0

        # Move the DWG itself
        src  = os.path.join(tmp_dir, dwg_files[0])
        dest = os.path.join(output_folder, export_name + ".dwg")
        if os.path.isfile(dest):
            os.remove(dest)
        shutil.move(src, dest)

        # Move sidecar files (raster images Revit writes alongside the DWG)
        # — genuine images only, per _DWG_SIDECAR_IMAGE_EXTS. Everything else
        # left in the temp folder (e.g. a .pcp file) is discarded here rather
        # than copied into the output folder, since it's not something users
        # want cluttering the export — it's simply left behind when the temp
        # folder itself is deleted in the finally block below.
        # Revit names image sidecars independently of our export_name prefix,
        # so we move every remaining IMAGE file in the temp folder as-is,
        # keeping its original filename. If a sidecar with the same name
        # already exists in the output folder it is treated as the same
        # image and left in place — overwriting it would be safe (identical
        # content) but skipping avoids an unnecessary write on large batch
        # exports.
        for sidecar in os.listdir(tmp_dir):
            sidecar_src  = os.path.join(tmp_dir, sidecar)
            if not os.path.isfile(sidecar_src):
                continue
            if not sidecar.lower().endswith(_DWG_SIDECAR_IMAGE_EXTS):
                continue   # e.g. .pcp — junk, left behind for cleanup
            sidecar_dest = os.path.join(output_folder, sidecar)
            if os.path.isfile(sidecar_dest):
                # Same filename already present — treated as identical image,
                # skip the move so the existing file is preserved.
                continue
            shutil.move(sidecar_src, sidecar_dest)

        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0
    finally:
        try:
            _queue_cleanup(tmp_dir)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Export one sheet to DXF — mirrors export_dwg exactly (DXFExportOptions
# inherits from DWGExportOptions in the Revit API, and doc.Export() behaves
# the same way: fileName is a PREFIX, Revit appends its own suffix).
# ---------------------------------------------------------------------------
def export_dxf(sheet, export_name, output_folder, dxf_opts):
    sheet_ids = List[ElementId]([sheet.Id])

    t0 = time.time()
    try:
        dxf_export = doc.Export.Overloads[str, str, ICollection[ElementId], DXFExportOptions]
    except Exception as e:
        return "Overload resolution failed: " + str(e), time.time() - t0

    tmp_dir = _short_tmpdir("es_dxf_")
    try:
        result = dxf_export(tmp_dir, "_tmp", sheet_ids, dxf_opts)

        dxf_files = [f for f in os.listdir(tmp_dir)
                     if f.lower().endswith(".dxf")]

        if not dxf_files:
            return "doc.Export succeeded={} but no .dxf found in temp folder".format(result), time.time() - t0

        src  = os.path.join(tmp_dir, dxf_files[0])
        dest = os.path.join(output_folder, export_name + ".dxf")
        if os.path.isfile(dest):
            os.remove(dest)
        shutil.move(src, dest)

        # Same sidecar-file handling as export_dwg — image sidecars only,
        # everything else (e.g. .pcp) is discarded, not moved.
        for sidecar in os.listdir(tmp_dir):
            sidecar_src  = os.path.join(tmp_dir, sidecar)
            if not os.path.isfile(sidecar_src):
                continue
            if not sidecar.lower().endswith(_DWG_SIDECAR_IMAGE_EXTS):
                continue
            sidecar_dest = os.path.join(output_folder, sidecar)
            if os.path.isfile(sidecar_dest):
                continue
            shutil.move(sidecar_src, sidecar_dest)

        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0
    finally:
        try:
            _queue_cleanup(tmp_dir)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Export one sheet to DWFx — mirrors export_dwg/export_dxf, but DWF/DWFx has a
# DIFFERENT overload shape than every other export format here: Revit's own
# error message (once the wrong overload was picked) revealed the real
# signature is Export(folder, prefix, ViewSet, DWFExportOptions) — a ViewSet
# of views/sheets, not an ICollection<ElementId> like DWG/DXF/PDF. Building
# the ViewSet from the sheet directly (not its ElementId) is required.
# ---------------------------------------------------------------------------
def export_dwfx(sheet, export_name, output_folder, dwfx_opts):
    t0 = time.time()

    try:
        dwfx_export = doc.Export.Overloads[str, str, ViewSet, DWFExportOptions]
    except Exception as e:
        return "Overload resolution failed: " + str(e), time.time() - t0

    view_set = ViewSet()
    view_set.Insert(sheet)

    tmp_dir = _short_tmpdir("es_dwfx_")
    # Revit's DWF/DWFx exporter throws "document is modifiable" required unless
    # called inside an open transaction — unlike PDF/DWG/DXF export, which run
    # fine with no transaction open. Nothing is actually changed, so the
    # transaction is always rolled back regardless of outcome.
    tx = Transaction(doc, "Kidzink - DWFx Export (no-op)")
    try:
        tx.Start()
        result = dwfx_export(tmp_dir, "_tmp", view_set, dwfx_opts)

        dwfx_files = [f for f in os.listdir(tmp_dir)
                      if f.lower().endswith((".dwfx", ".dwf"))]

        if not dwfx_files:
            return "doc.Export succeeded={} but no .dwfx/.dwf found in temp folder".format(result), time.time() - t0

        # Normalize to .dwfx regardless of the internal extension Revit wrote,
        # so the destination filename always matches what callers expect.
        src  = os.path.join(tmp_dir, dwfx_files[0])
        dest = os.path.join(output_folder, export_name + ".dwfx")
        if os.path.isfile(dest):
            os.remove(dest)
        shutil.move(src, dest)

        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0
    finally:
        try:
            tx.RollBack()   # never commit — this is export-only, no model change
        except Exception:
            pass
        try:
            _queue_cleanup(tmp_dir)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Export one sheet to DWF. Same overload/transaction requirement as DWFx —
# Revit has no separate DWF-only export path; DWFExportOptions and the
# ViewSet-based overload are shared. Only accepts genuine .dwf output — if
# Revit writes .dwfx instead, that is reported as a failure rather than
# silently relabeled, since a request for DWF specifically may depend on the
# legacy binary format rather than an XPS container wearing a .dwf extension.
# ---------------------------------------------------------------------------
def export_dwf(sheet, export_name, output_folder, dwf_opts):
    t0 = time.time()

    try:
        dwf_export = doc.Export.Overloads[str, str, ViewSet, DWFExportOptions]
    except Exception as e:
        return "Overload resolution failed: " + str(e), time.time() - t0

    view_set = ViewSet()
    view_set.Insert(sheet)

    tmp_dir = _short_tmpdir("es_dwf_")
    tx = Transaction(doc, "Kidzink - DWF Export (no-op)")
    try:
        tx.Start()
        result = dwf_export(tmp_dir, "_tmp", view_set, dwf_opts)

        dwf_files  = [f for f in os.listdir(tmp_dir) if f.lower().endswith(".dwf")]
        dwfx_files = [f for f in os.listdir(tmp_dir) if f.lower().endswith(".dwfx")]

        if not dwf_files:
            if dwfx_files:
                return ("Revit wrote .dwfx, not legacy .dwf — this Revit "
                         "install/version may not support true DWF export "
                         "via the API"), time.time() - t0
            return "doc.Export succeeded={} but no .dwf found in temp folder".format(result), time.time() - t0

        src  = os.path.join(tmp_dir, dwf_files[0])
        dest = os.path.join(output_folder, export_name + ".dwf")
        if os.path.isfile(dest):
            os.remove(dest)
        shutil.move(src, dest)

        return True, time.time() - t0

    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0
    finally:
        try:
            tx.RollBack()
        except Exception:
            pass
        try:
            _queue_cleanup(tmp_dir)
        except Exception:
            pass


# ---------------------------------------------------------------------------
# Export a single view to PNG or JPEG via doc.ExportImage.
# Revit auto-appends the extension — do NOT include it in FilePath.
# Resolution string: "Low (72 DPI)" | "Medium (150 DPI)" | "High (300 DPI)" | "Very High (600 DPI)"
# ---------------------------------------------------------------------------
_VIEW_RASTER_DPI_MAP = {
    "Low (72 DPI)":        ImageResolution.DPI_72,
    "Medium (150 DPI)":    ImageResolution.DPI_150,
    "High (300 DPI)":      ImageResolution.DPI_300,
    "Very High (600 DPI)": ImageResolution.DPI_600,
}

def export_view_raster(view, export_name, output_folder, resolution_str, file_type):
    """Export a view to PNG or JPEG.

    file_type: ImageFileType.PNG or ImageFileType.JPEGLossless
    Returns (True, elapsed) on success or (error_str, elapsed) on failure.
    """
    t0 = time.time()
    ext = "png" if file_type == ImageFileType.PNG else "jpg"
    dest = os.path.join(output_folder, export_name + "." + ext)
    # Revit writes: <FilePath>.<ext> — FilePath must NOT include the extension
    stem = os.path.join(output_folder, export_name)
    try:
        opts = ImageExportOptions()
        opts.ExportRange          = ExportRange.SetOfViews
        opts.FilePath             = stem
        opts.ImageResolution      = _VIEW_RASTER_DPI_MAP.get(resolution_str, ImageResolution.DPI_300)
        opts.HLRandWFViewsFileType = file_type
        opts.ShadowViewsFileType  = file_type
        opts.SetViewsAndSheets(List[ElementId]([view.Id]))
        doc.ExportImage(opts)
        # Revit may append view name suffix — find the file
        if not os.path.isfile(dest):
            candidates = [
                f for f in os.listdir(output_folder)
                if f.startswith(export_name) and f.lower().endswith("." + ext)
            ]
            if candidates:
                os.rename(os.path.join(output_folder, candidates[0]), dest)
            else:
                return "ExportImage succeeded but output file not found", time.time() - t0
        return True, time.time() - t0
    except Exception as e:
        return "EXCEPTION: " + str(e), time.time() - t0


