# ---------------------------------------------------------------------------
# Filename profile persistence
# %APPDATA%\Kidzink\export_sheets_fn_profiles.json
# {"ProfileName": {"params": [...], "separators": [...], "order": [...]}}
# ---------------------------------------------------------------------------

_FN_PROFILES_PATH = None
_FN_PROFILES_INIT_ERROR = None
try:
    _app_dir = os.path.join(
        os.environ.get("APPDATA", tempfile.gettempdir()), "Kidzink"
    )
    if not os.path.isdir(_app_dir):
        os.makedirs(_app_dir)
    _FN_PROFILES_PATH = os.path.join(_app_dir, "export_sheets_fn_profiles.json")
except Exception as _init_err:
    # Previously swallowed silently — if the Kidzink folder can't be created
    # (permissions, path issue), EVERY save/load below fails from the start
    # with zero indication why. Keep the reason so the wizard can warn once,
    # instead of the user seeing profile edits that just quietly never stick.
    _FN_PROFILES_INIT_ERROR = str(_init_err)

def _load_all_profiles():
    if _FN_PROFILES_INIT_ERROR:
        _bring_revit_forward()
        forms.alert(
            "Could not access the profiles folder, so filename profiles "
            "cannot be loaded or saved this session:\n\n{}\n\n"
            "Using an empty 'Default' profile for now. Check permissions on "
            "%APPDATA%\\Kidzink\\.".format(_FN_PROFILES_INIT_ERROR),
            title="Profile Storage Unavailable")
        return {"Default": {"params": [], "separators": []}}
    if _FN_PROFILES_PATH and os.path.isfile(_FN_PROFILES_PATH):
        try:
            with open(_FN_PROFILES_PATH, "r") as _f:
                data = _json.loads(_f.read())
            if isinstance(data, dict) and data:
                return data
        except Exception as _load_err:
            # A profiles file EXISTS but failed to parse (corrupted, partial
            # write, locked/mid-sync). Silently falling back to a blank
            # Default here previously looked exactly like "all my profiles
            # vanished" — tell the user instead of guessing for them.
            _bring_revit_forward()
            forms.alert(
                "The saved filename profiles file exists but could not be "
                "read, so it will NOT be overwritten automatically:\n\n"
                "{}\n\nError: {}\n\n"
                "Using an empty 'Default' profile for this session only. "
                "Your existing profiles are still on disk — fix or restore "
                "that file before saving new profiles, or they'll be saved "
                "under Default and the original file left as-is.".format(
                    _FN_PROFILES_PATH, str(_load_err)),
                title="Profiles File Could Not Be Read")
    return {"Default": {"params": [], "separators": []}}

def _save_all_profiles(profiles_dict):
    """Write profiles_dict to disk. Returns True on success, False on
    failure — callers MUST check this and warn the user, since a silent
    failure here means every profile edit/create/delete in the session
    just vanishes with no indication anything went wrong."""
    if not _FN_PROFILES_PATH:
        return False
    try:
        with open(_FN_PROFILES_PATH, "w") as _f:
            _f.write(_json.dumps(profiles_dict))
        return True
    except Exception as _save_err:
        _bring_revit_forward()
        forms.alert(
            "Filename profile changes could NOT be saved to disk:\n\n"
            "{}\n\nError: {}\n\n"
            "This usually means the file is locked (open elsewhere, syncing "
            "via OneDrive) or you don't have write permission to that "
            "folder. Any New Profile / Save Profile / Delete Profile changes "
            "made in this session were NOT persisted — you'll need to redo "
            "them once the issue above is resolved.".format(
                _FN_PROFILES_PATH, str(_save_err)),
            title="Profile Save Failed")
        return False


# ---------------------------------------------------------------------------
# Last-used filename profile — separate tiny file (not folded into the
# profiles JSON) so a corrupt/locked profiles file can never take this
# convenience feature down with it, and vice versa. Read once at startup to
# pre-select the profile the user used last time; written after a successful
# (non-cancelled) wizard session — see _save_last_profile_name() call below.
# ---------------------------------------------------------------------------
_LAST_PROFILE_PATH = None
try:
    if _app_dir:
        _LAST_PROFILE_PATH = os.path.join(_app_dir, "export_sheets_last_profile.txt")
except Exception:
    pass

def _load_last_profile_name():
    if _LAST_PROFILE_PATH and os.path.isfile(_LAST_PROFILE_PATH):
        try:
            with open(_LAST_PROFILE_PATH, "r") as _f:
                name = _f.read().strip()
            return name if name else None
        except Exception:
            return None
    return None

def _save_last_profile_name(name):
    if not _LAST_PROFILE_PATH or not name:
        return
    try:
        with open(_LAST_PROFILE_PATH, "w") as _f:
            _f.write(name)
    except Exception:
        pass   # non-critical convenience feature — never block/warn on this



# ---------------------------------------------------------------------------
# Step 1: Collect available Drawing List schedules AND every sheet in the
# model (always needed, both for the interactive wizard's Sheet Source step —
# which offers both a By Schedule dropdown and a By Selection checklist — and
# to re-resolve the chosen source on a headless scheduled re-run).
# ---------------------------------------------------------------------------
all_schedules = get_sheet_schedules()
sched_names   = [s.Name for s in all_schedules]
sched_by_name = {s.Name: s for s in all_schedules}

all_model_sheets = get_all_model_sheets()
if not all_model_sheets:
    forms.alert(
        "No sheets found in this project.",
        title="No Sheets Found",
        exitscript=True
    )
sheet_by_number = {s.SheetNumber: s for s in all_model_sheets}
_perf("collectors (schedules+sheets)")

# ---------------------------------------------------------------------------
# Scheduled Export support — persistent, session-wide scheduler
#
# A per-click pushbutton script cannot reliably keep something alive to fire
# later: testing showed BOTH a DispatcherTimer+ExternalEvent approach and a
# UIApplication.Idling subscription registered directly from here succeed at
# *registering*, but never actually fire once script.py's own execution has
# returned — no crash, no log entry, nothing. Whatever pyRevit does to a
# script's state after it finishes, neither mechanism survived it.
#
# The fix: this script no longer tries to keep anything alive itself. When
# Schedule Export is enabled, it just writes a small "pending schedule" JSON
# file describing everything needed to re-run the export later, then exits.
# A separate `startup.py` at the extension root — loaded ONCE by pyRevit when
# the extension loads, and alive for the whole Revit session — owns the one
# persistent Idling subscription that polls for this file and, when the
# target time arrives, re-invokes THIS script.py headlessly (injecting the
# saved state instead of showing the wizard) to actually perform the export.
# That keeps all the export logic in one place (no duplicated code to drift)
# while moving the "who fires this later" responsibility to something that
# actually persists.
# ---------------------------------------------------------------------------
import System as _SystemNS
import tempfile as _tempfile

_SCHED_LOG_PATH = os.path.join(_tempfile.gettempdir(), "kidzink_export_schedule.log")

def _sched_log(msg):
    try:
        line = "{}  {}\n".format(_SystemNS.DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss"), msg)
        with open(_SCHED_LOG_PATH, "a") as _lf:
            _lf.write(line)
    except Exception:
        pass

# Unconditional proof-of-life line — written every run regardless of mode,
# so a broken log path/permissions is never confused with a scheduling bug.
_sched_log("script.py started (mode: %s)" % (
    "HEADLESS" if globals().get("_KIDZINK_HEADLESS_STATE") is not None else "interactive"))

_PENDING_SCHEDULE_PATH = os.path.join(
    os.environ.get("APPDATA", _tempfile.gettempdir()), "Kidzink", "pending_export_schedule.json")

def _save_pending_schedule(state):
    d = os.path.dirname(_PENDING_SCHEDULE_PATH)
    try:
        if not os.path.isdir(d):
            os.makedirs(d)
        with open(_PENDING_SCHEDULE_PATH, "w") as _f:
            _f.write(_json.dumps(state))
        _sched_log("Pending schedule saved: target=%s folder=%s" % (
            state.get("target"), state.get("output_folder")))
    except Exception as _pe:
        _sched_log("Failed to save pending schedule: %s" % str(_pe))
        forms.alert(
            "Could not save the scheduled export request:\n%s" % str(_pe),
            title="Scheduled Export Error")

# ---------------------------------------------------------------------------
# Headless dispatch: _KIDZINK_HEADLESS_STATE is injected into this script's
# globals by startup.py when it re-runs this file at the scheduled time. Its
# ABSENCE (normal button click) means run the interactive wizard as usual.
# ---------------------------------------------------------------------------
_KIDZINK_HEADLESS_STATE = globals().get("_KIDZINK_HEADLESS_STATE", None)

if _KIDZINK_HEADLESS_STATE is None:
    # =========================================================================
    # INTERACTIVE PATH — normal button click, show the wizard
    # =========================================================================

    # -------------------------------------------------------------------
    # Step 2.5 + Step 3 combined: single wizard window
    # Sheet Source -> Profile (with Edit Profile fold-out) -> Export Settings.
    # Replaces the five separate custom dialogs and the FlexForm settings dialog.
    # -------------------------------------------------------------------
    from wizard_ui import ExportWizardWindow

    # Sheet parameters are the same across every schedule (they live on the
    # ViewSheet element itself), so the parameter checklist can be seeded from
    # ANY sheet in the project — it does not need to wait for a schedule pick.
    _sample_sheets = _get_all_view_sheets()
    if not _sample_sheets:
        forms.alert(
            "No sheets found in this project.",
            title="No Sheets Found",
            exitscript=True
        )
    _all_params    = get_all_sheet_params(_sample_sheets[0])
    _param_by_name = {pf["name"]: pf for pf in _all_params}
    _all_profiles  = _load_all_profiles()
    _perf("sheet params + profiles")

    # GetElementCount() avoids materializing every collection element
    # just to test for existence — a cheap presence check.
    project_has_collections = (
        FilteredElementCollector(doc).OfClass(SheetCollection).GetElementCount() > 0
    )

    _dwg_ver_opts = list(_dwg_ver_opts_global)
    _folder_opts  = (["Type > Sheet Collection", "Sheet Collection > Type"]
                      if project_has_collections else [])

    # Default profile: the profile used last time (if it still exists),
    # else "Default", else whichever profile sorts first. Preselected params
    # fall back to Sheet Number/Sheet Name only if the resolved profile has
    # none saved.
    _last_used_profile_name = _load_last_profile_name()
    _is_last_used_profile = bool(_last_used_profile_name and _last_used_profile_name in _all_profiles)
    if _is_last_used_profile:
        _default_profile_name = _last_used_profile_name
    else:
        _default_profile_name = "Default" if "Default" in _all_profiles else sorted(_all_profiles.keys())[0]
    _ee   = _all_profiles.get(_default_profile_name, {})
    _pp   = _ee.get("params", [])
    _pre  = ([n for n in _pp if n in _param_by_name] if _pp
             else [pf["name"] for pf in _all_params
                   if pf["is_sheet_num"] or pf["is_sheet_name"]])

    # Sheet options for the By Selection sub-mode's checklist, in the same
    # sorted order as all_model_sheets. If the user already had sheets
    # selected in the Project Browser/view before running this tool,
    # preselect those (only relevant if they switch to By Selection).
    _sheet_options = [{"number": s.SheetNumber, "name": s.Name,
                       "collection": get_collection_name(s)} for s in all_model_sheets]
    _perf("sheet_options (collection names)")
    _preselected_sheet_numbers = []
    try:
        _sel_ids = list(uidoc.Selection.GetElementIds())
        if _sel_ids:
            _sel_sheet_numbers = set()
            for _sid in _sel_ids:
                _el = doc.GetElement(_sid)
                if isinstance(_el, ViewSheet):
                    _sel_sheet_numbers.add(_el.SheetNumber)
            _preselected_sheet_numbers = [
                s["number"] for s in _sheet_options if s["number"] in _sel_sheet_numbers
            ]
    except Exception:
        pass

    # Links for the Pre-Export Actions "Reload Links" checklist.
    # PERF: resolving each link's user-visible path (GetExternalFileReference /
    # ConvertModelPathToUserVisiblePath) is comparatively slow — especially for
    # cloud/network links — and the checklist lives in a collapsed section that
    # defaults OFF. So we only do a cheap "are there any links at all?" count
    # here (to decide whether to show the control), and hand the wizard a
    # provider it calls lazily the first time the user actually ticks Reload
    # Links. This keeps the full link scan off the dialog-open path.
    try:
        _has_links = FilteredElementCollector(doc)\
            .OfClass(RevitLinkInstance).GetElementCount() > 0
    except Exception:
        _has_links = False

    def _link_options_provider():
        return [{"name": l["name"], "path_display": l["path_display"]}
                for l in get_all_links()]

    # View Source — collect all non-template, non-sheet views in the project.
    # Flat list (not schedule-dependent). Unsupported types are flagged.
    _view_rows_data = []
    try:
        from Autodesk.Revit.DB import View, ViewType
        _SKIP_VIEW_TYPES = set()
        for _vtn in ("Schedule", "Legend", "DrawingSheet",
                      "ProjectBrowser", "SystemBrowser", "Undefined"):
            _vt = getattr(ViewType, _vtn, None)
            if _vt is not None:
                _SKIP_VIEW_TYPES.add(_vt)
        _all_views = FilteredElementCollector(doc).OfClass(View).ToElements()
        for _v in sorted(_all_views, key=lambda x: x.Name.lower()):
            if _v.IsTemplate:
                continue
            if isinstance(_v, ViewSheet):
                continue
            if _v.ViewType in _SKIP_VIEW_TYPES:
                continue   # exclude non-exportable views entirely
            _vt_name = str(_v.ViewType).replace("ViewType.", "")
            _view_rows_data.append({
                "name": _v.Name,
                "view_type": _vt_name,
                "is_exportable": True,
                "is_checked": False,
                "view": _v,
            })
    except Exception:
        _view_rows_data = []
    _perf("view list collected")

    wiz = ExportWizardWindow(
        os.path.join(SCRIPT_DIR, "window.xaml"),
        param_names=[pf["name"] for pf in _all_params],
        all_profiles=_all_profiles,
        preselected=_pre,
        sep_options=["-", "_", "(none)"],
        profile_name=_default_profile_name,
        format_opts=["PDF", "PDF Merge", "DWG", "DXF", "DWFx", "DWFx Merge", "DWF", "DWF Merge"],
        default_formats=["PDF"],
        dwfx_quality_opts=["Default", "Low", "Medium", "High", "Best"],
        dwf_quality_opts=["Default", "Low", "Medium", "High", "Best"],
        pdf_quality_opts=["Low (72 DPI)", "Medium (150 DPI)",
                           "High (300 DPI)", "Very High (600 DPI)"],
        pdf_processing_opts=["Vector", "Raster"],
        dwg_version_opts=_dwg_ver_opts,
        folder_opts=_folder_opts,
        schedule_source_opts=sched_names,
        sheet_options=_sheet_options,
        preselected_sheet_numbers=_preselected_sheet_numbers,
        link_options=None,
        has_links=_has_links,
        link_provider=_link_options_provider,
        is_workshared=doc.IsWorkshared,
        is_last_used_profile=_is_last_used_profile,
        view_rows_data=_view_rows_data)
    _perf("wizard built (xaml+populate)")
    _perf_dump()   # no-op unless _OPEN_PERF is True
    wiz.ShowDialog()

    # Persist whatever profile changes happened DURING the wizard session
    # (New Profile, Delete Profile, explicit Save Profile) regardless of
    # whether the user goes on to Export or Cancels — these are deliberate
    # actions the user took, separate from the export decision itself.
    # wiz.all_profiles is the SAME dict object as _all_profiles (passed by
    # reference), so any in-wizard mutations are already reflected here.
    # _save_all_profiles() already alerts on failure (locked file, no
    # permission, etc.) — no silent "looked like it saved but didn't" here.
    _save_all_profiles(_all_profiles)

    if not wiz.result:
        script.exit()

    # Remember this profile for next time — only after a confirmed (not
    # cancelled) session, so backing out of the wizard doesn't overwrite
    # what was actually last used for a real export.
    _save_last_profile_name(wiz.profile_name)

    _wv = wiz.result
    source_mode = _wv.get("source_mode", "schedule")

    # Resolve sheets from whichever Sheet Source sub-mode the user used.
    _include_views_flag = _wv.get("include_views", False)
    _view_formats_flag  = _wv.get("view_formats", [])
    _views_only = _include_views_flag and bool(_view_formats_flag)

    if source_mode == "selection":
        selected_sheet_numbers = _wv["selected_sheets"]
        sheets = [sheet_by_number[n] for n in selected_sheet_numbers if n in sheet_by_number]
        if not sheets and not _views_only:
            forms.alert(
                "No sheets found for the selected sheet numbers.\n"
                "The model may have changed since the wizard opened — try again.",
                title="No Sheets Found",
                exitscript=True
            )
        source_label = u"{} sheet(s) selected".format(len(sheets))
    else:
        selected_name     = _wv["schedule_source"]
        selected_schedule = sched_by_name.get(selected_name)
        if selected_schedule is None and not _views_only:
            forms.alert(
                "The selected schedule could not be resolved: %s" % selected_name,
                title="Schedule Not Found",
                exitscript=True
            )
        sheets = get_sheets_from_schedule(selected_schedule) if selected_schedule else []
        if not sheets and not _views_only:
            forms.alert(
                "No sheets found in the selected schedule.\n"
                "Check that the schedule has rows and is not filtered to empty.",
                title="No Sheets Found",
                exitscript=True
            )
        source_label = selected_schedule.Name if selected_schedule else u"Views only"

    selected_param_fields = [_param_by_name[p] for p in _wv["parameters"] if p in _param_by_name]
    separators            = list(_wv["separators"])

    export_formats = _wv["export_formats"]
    dwfx_quality   = _wv.get("dwfx_quality", "Default")
    dwf_quality    = _wv.get("dwf_quality", "Default")
    pdf_quality    = _wv["pdf_quality"]
    pdf_processing = _wv["pdf_processing"]
    hide_crop      = _wv["hide_crop"]
    hide_ref       = _wv["hide_ref"]
    hide_scope     = _wv["hide_scope"]
    hide_view_tags = _wv["hide_view_tags"]
    dwg_version    = _wv["dwg_version"]
    view_formats      = _wv.get("view_formats", ["PNG", "JPEG"])
    view_dwg_version  = _wv.get("view_dwg_version") or dwg_version
    view_resolution   = _wv.get("view_resolution", "High (300 DPI)")
    folder_mode    = _wv["folder_mode"] or "Type > Sheet Collection"
    do_compress    = _wv["compress_pdf"]

    selected_name = u"{} — [{}] {}".format(
        source_label, wiz.profile_name,
        "".join(p["name"] + (separators[i] if i < len(separators) else "")
                for i, p in enumerate(selected_param_fields))
    )

    # High quality + Raster warning (interactive only — no one to click
    # Cancel on a headless scheduled run, so this is skipped in that branch).
    do_pdf_for_warning = ("PDF" in export_formats) or ("PDF Merge" in export_formats)
    if do_pdf_for_warning and pdf_quality in ("High (300 DPI)", "Very High (600 DPI)") and pdf_processing == "Raster":
        _bring_revit_forward()
        _wt = TaskDialog("High Quality Warning")
        _wt.TitleAutoPrefix = False
        _wt.MainInstruction = "{} + Raster selected".format(pdf_quality)
        _wt.MainContent     = (
            "{} combined with Raster processing will be significantly "
            "slower for sheets with 3D views, perspectives, or raster images.\n\n"
            "Consider Vector processing for faster exports.".format(pdf_quality)
        )
        _wt.CommonButtons   = TaskDialogCommonButtons.Ok | TaskDialogCommonButtons.Cancel
        _wt.DefaultButton   = TaskDialogResult.Ok
        if _wt.Show() != TaskDialogResult.Ok:
            script.exit()

    # ---------------------------------------------------------------------
    # Step 4: Determine output folder / dispatch scheduling
    # Scheduled exports already asked for + captured the folder during the
    # wizard's own confirm flow (Proceed/Cancel). Instead of trying to wait
    # for that time ourselves, save a pending-schedule descriptor for
    # startup.py's persistent Idling handler to pick up, then exit —
    # immediate exports ask for the folder now and run right away, as before.
    # ---------------------------------------------------------------------
    if _wv.get("schedule_enabled"):
        output_folder = _wv.get("output_folder")
        if not output_folder:
            script.exit()

        _pending_state = {
            "script_path_parts": ["KidzinkTools.tab", "Export.panel",
                                   "Sheet Export.pushbutton", "script.py"],
            "target":         _wv["scheduled_datetime"].ToString("o"),  # ISO 8601 round-trip
            "output_folder":  output_folder,
            "doc_path":       doc.PathName,
            "source_mode":    source_mode,
            "schedule_name":  selected_schedule.Name if source_mode == "schedule" else None,
            "sheet_numbers":  selected_sheet_numbers if source_mode == "selection" else None,
            "profile_name":   wiz.profile_name,
            "parameters":     [p["name"] for p in selected_param_fields],
            "separators":     separators,
            "sync_central":       _wv.get("sync_central", False),
            "reload_links":       _wv.get("reload_links", False),
            "reload_link_names":  _wv.get("reload_link_names", []),
            "export_formats": export_formats,
            "dwfx_quality":   dwfx_quality,
            "dwf_quality":    dwf_quality,
            "pdf_quality":    pdf_quality,
            "pdf_processing": pdf_processing,
            "hide_crop":      hide_crop,
            "hide_ref":       hide_ref,
            "hide_scope":     hide_scope,
            "hide_view_tags": hide_view_tags,
            "dwg_version":    dwg_version,
            "folder_mode":    folder_mode,
            "compress_pdf":   do_compress,
            "include_report": _wv.get("include_report", True),
            "view_formats":      view_formats,
            "view_dwg_version":  view_dwg_version,
            "view_resolution":   view_resolution,
        }
        _save_pending_schedule(_pending_state)

        _log_exists = os.path.isfile(_SCHED_LOG_PATH)
        forms.alert(
            "Export scheduled for {0}.\n\n"
            "Keep Revit open with this document — the Kidzink background "
            "scheduler (startup.py) will run the export automatically at "
            "the scheduled time using:\n{1}\n\n"
            "(Diagnostic log {2}: {3})".format(
                _wv["scheduled_datetime"].ToString("dddd, MMMM d, yyyy  HH:mm"),
                output_folder,
                "found" if _log_exists else "NOT FOUND", _SCHED_LOG_PATH),
            title="Export Scheduled"
        )
        script.exit()
    else:
        output_folder = forms.pick_folder()
        if not output_folder:
            script.exit()

else:
    # =========================================================================
    # HEADLESS PATH — re-invoked by startup.py's persistent Idling handler at
    # the scheduled time. No wizard, no interactive dialogs (besides failure
    # alerts) — everything is rebuilt from the saved state dict.
    # =========================================================================
    _hs = _KIDZINK_HEADLESS_STATE
    _hs_mode = _hs.get("source_mode", "schedule")

    if _hs_mode == "selection":
        # Re-resolve sheets by number fresh from the CURRENT document rather
        # than holding onto element references from wizard-time — sheets
        # could have been renumbered, deleted, or added since scheduling.
        _current_sheets = get_all_model_sheets()
        _sheet_by_number_now = {s.SheetNumber: s for s in _current_sheets}
        _wanted_numbers = _hs.get("sheet_numbers") or []
        sheets = [_sheet_by_number_now[n] for n in _wanted_numbers if n in _sheet_by_number_now]
        _missing_numbers = [n for n in _wanted_numbers if n not in _sheet_by_number_now]
        if _missing_numbers:
            _sched_log("Headless run: {} sheet(s) no longer found by number: {}".format(
                len(_missing_numbers), ", ".join(_missing_numbers)))
        if not sheets:
            _sched_log("Headless run: none of the scheduled sheet numbers were found — aborting")
            script.exit()
        _hs_source_label = u"{} sheet(s) selected".format(len(sheets))
    else:
        selected_schedule = sched_by_name.get(_hs["schedule_name"])
        if selected_schedule is None:
            _sched_log("Headless run: schedule '%s' not found — aborting" % _hs.get("schedule_name"))
            script.exit()
        sheets = get_sheets_from_schedule(selected_schedule)
        if not sheets:
            _sched_log("Headless run: no sheets in schedule '%s' — aborting" % selected_schedule.Name)
            script.exit()
        _hs_source_label = selected_schedule.Name

    _sample_sheets = _get_all_view_sheets()
    _all_params    = get_all_sheet_params(_sample_sheets[0]) if _sample_sheets else []
    _param_by_name = {pf["name"]: pf for pf in _all_params}

    selected_param_fields = [_param_by_name[p] for p in _hs["parameters"] if p in _param_by_name]
    separators            = list(_hs["separators"])

    export_formats = _hs.get("export_formats", [_hs.get("export_format", "PDF")])
    dwfx_quality   = _hs.get("dwfx_quality", "Default")
    dwf_quality    = _hs.get("dwf_quality", "Default")
    pdf_quality    = _hs["pdf_quality"]
    pdf_processing = _hs["pdf_processing"]
    hide_crop      = _hs["hide_crop"]
    hide_ref       = _hs["hide_ref"]
    hide_scope     = _hs["hide_scope"]
    hide_view_tags = _hs["hide_view_tags"]
    dwg_version    = _hs["dwg_version"]
    folder_mode    = _hs["folder_mode"] or "Type > Sheet Collection"
    do_compress    = _hs["compress_pdf"]
    output_folder  = _hs["output_folder"]
    view_formats     = _hs.get("view_formats", ["PNG", "JPEG"])
    view_dwg_version = _hs.get("view_dwg_version") or dwg_version
    view_resolution  = _hs.get("view_resolution", "High (300 DPI)")

    selected_name = u"{} — [{}] {}".format(
        _hs_source_label, _hs.get("profile_name", "Default"),
        "".join(p["name"] + (separators[i] if i < len(separators) else "")
                for i, p in enumerate(selected_param_fields))
    )

    # GetElementCount() avoids materializing every collection element
    # just to test for existence — a cheap presence check.
    project_has_collections = (
        FilteredElementCollector(doc).OfClass(SheetCollection).GetElementCount() > 0
    )

    _wv = {
        "include_report":     _hs.get("include_report", True),
        "sync_central":       _hs.get("sync_central", False),
        "reload_links":       _hs.get("reload_links", False),
        "reload_link_names":  _hs.get("reload_link_names", []),
    }

    _sched_log("Headless run: variables rebuilt, proceeding to export")


# =============================================================================
# SHARED — both the interactive and headless paths converge here before the
# actual export runs.
# =============================================================================

# Derive the PDF24 CLI profile ID directly from the PDF quality the user already
# selected above. PDF24 CLI profile IDs: "low","medium","good","high","best".
# These are passed via -profile to -applyProfile; no dialog appears when supplied.
# PDF24 CLI profile IDs require the "default/" prefix — just the name
# alone (e.g. "good") is NOT recognised and triggers the selector dialog.
_PDF_QUALITY_TO_PROFILE = {
    "Low (72 DPI)":        "default/low",
    "Medium (150 DPI)":    "default/medium",
    "High (300 DPI)":      "default/good",
    "Very High (600 DPI)": "default/best",
}
compress_profile = _PDF_QUALITY_TO_PROFILE.get(pdf_quality, "default/good")

do_pdf          = "PDF" in export_formats
do_pdf_combined = "PDF Merge" in export_formats
do_dwg          = "DWG" in export_formats
do_dxf          = "DXF" in export_formats
do_dwfx         = "DWFx" in export_formats
do_dwfx_combined = "DWFx Merge" in export_formats
do_dwf          = "DWF" in export_formats
do_dwf_combined = "DWF Merge" in export_formats

# Human-readable label for previews/reports — replaces the old single
# combinatorial string (e.g. "PDF + PDF Merge + DWG") now that any
# combination of formats can be ticked independently.
export_format_label = " + ".join(export_formats) if export_formats else "(none)"

def _run_export(output_folder):
    """The actual export routine (preview + export loop + report).
    Runs immediately for a normal export, or later via the Idling event
    when Schedule Export was enabled in the wizard's Settings dialog.
    """
    # ---------------------------------------------------------------------------
    # Step 4.5: Pre-Export Actions — Sync with Central, then Reload Links.
    # Both default OFF. Runs before anything else (before the preview is even
    # built), since reloaded links can change titleblocks/geometry that the
    # preview and export should reflect. Failures here are surfaced but do
    # NOT silently abort the whole export — for an interactive run the user
    # is asked whether to proceed anyway; for a headless scheduled run (no
    # one to ask) it proceeds and logs the failure, since aborting a
    # scheduled export over a non-fatal sync/reload hiccup would be worse.
    # ---------------------------------------------------------------------------
    _is_headless = globals().get("_KIDZINK_HEADLESS_STATE") is not None

    if _wv.get("sync_central"):
        _sync_ok, _sync_err = sync_with_central()
        if not _sync_ok:
            if _is_headless:
                try:
                    _sched_log("Sync with Central failed (proceeding anyway): %s" % _sync_err)
                except Exception:
                    pass
            else:
                _bring_revit_forward()
                _sync_td = TaskDialog("Sync with Central Failed")
                _sync_td.TitleAutoPrefix = False
                _sync_td.MainInstruction = "Synchronize with Central failed."
                _sync_td.MainContent = (
                    "{}\n\nProceed with the export anyway, or cancel?".format(_sync_err)
                )
                _sync_td.CommonButtons = TaskDialogCommonButtons.Yes | TaskDialogCommonButtons.Cancel
                _sync_td.DefaultButton = TaskDialogResult.Yes
                if _sync_td.Show() != TaskDialogResult.Yes:
                    script.exit()

    if _wv.get("reload_links"):
        _link_names = _wv.get("reload_link_names") or []
        if _link_names:
            _reload_ok, _reload_failed = reload_selected_links(_link_names)
            if _reload_failed:
                _fail_lines = "\n".join("  {} — {}".format(n, e) for n, e in _reload_failed)
                if _is_headless:
                    try:
                        _sched_log("Reload Links: {} failed:\n{}".format(
                            len(_reload_failed), _fail_lines))
                    except Exception:
                        pass
                else:
                    _bring_revit_forward()
                    _reload_td = TaskDialog("Reload Links — Some Failed")
                    _reload_td.TitleAutoPrefix = False
                    _reload_td.MainInstruction = "{} of {} link(s) failed to reload.".format(
                        len(_reload_failed), len(_link_names))
                    _reload_td.MainContent = (
                        "{}\n\nProceed with the export anyway, or cancel?".format(_fail_lines)
                    )
                    _reload_td.CommonButtons = TaskDialogCommonButtons.Yes | TaskDialogCommonButtons.Cancel
                    _reload_td.DefaultButton = TaskDialogResult.Yes
                    if _reload_td.Show() != TaskDialogResult.Yes:
                        script.exit()

    # ---------------------------------------------------------------------------
    # Auto-dismiss Revit's native pop-up dialogs for the duration of the
    # export. Without this, dialogs like "Printing raster images..." block
    # the thread until the user clicks OK — fatal for unattended exports.
    # Unsubscribed at the end of this function (see _unsubscribe below).
    # ---------------------------------------------------------------------------
    _subscribe_auto_dismiss()

    # ---------------------------------------------------------------------------
    # Step 5: Build options ONCE before the loop
    # ---------------------------------------------------------------------------
    # DWG version map

    dwg_opts = get_dwg_options() if do_dwg else None
    if dwg_opts:
        _fallback_ver = list(_DWG_VERSION_MAP.values())[0] if _DWG_VERSION_MAP else ACADVersion.R2018
        _safe_set(dwg_opts, "FileVersion", _DWG_VERSION_MAP.get(dwg_version, _fallback_ver))

    dxf_opts = get_dxf_options() if do_dxf else None
    if dxf_opts:
        _fallback_ver = list(_DWG_VERSION_MAP.values())[0] if _DWG_VERSION_MAP else ACADVersion.R2018
        _safe_set(dxf_opts, "FileVersion", _DWG_VERSION_MAP.get(dwg_version, _fallback_ver))

    dwfx_opts = get_dwfx_options(dwfx_quality) if (do_dwfx or do_dwfx_combined) else None
    dwf_opts  = get_dwf_options(dwf_quality)   if (do_dwf or do_dwf_combined) else None

    # Bundle PDF settings — used by both per-sheet PDF and combined PDF
    _pdf_settings = {
        "quality":        pdf_quality,
        "processing":     pdf_processing,
        "hide_crop":      hide_crop,
        "hide_ref":       hide_ref,
        "hide_scope":     hide_scope,
        "hide_view_tags": hide_view_tags,
    }

    # ---------------------------------------------------------------------------
    # Step 6: Build preview — compute filenames, flag missing fields
    # ---------------------------------------------------------------------------
    preview_rows = []
    any_warnings = False

    for sheet in sheets:
        filename = build_filename_from_params(sheet, selected_param_fields, separators)
        missing = [
            pf["name"] for pf in selected_param_fields
            if not get_param_value(sheet, pf)
        ]
        has_warn = len(missing) > 0
        if has_warn:
            any_warnings = True
        preview_rows.append({
            "sheet":    sheet,
            "filename": filename,
            "missing":  missing,
            "warn":     has_warn,
        })

    # ---------------------------------------------------------------------------
    # Step 7: (preview removed — HTML report covers this when enabled)
    # ---------------------------------------------------------------------------
    # ---------------------------------------------------------------------------
    # Step 8: Export loop — with per-sheet timing
    # ---------------------------------------------------------------------------
    exported_pdf  = []   # list of (filename, elapsed, path)
    exported_dwg  = []   # list of (filename, elapsed, path)
    exported_dxf  = []   # list of (filename, elapsed, path)
    exported_dwfx = []   # list of (filename, elapsed, path)
    exported_dwf  = []   # list of (filename, elapsed, path)
    exported_pdf_combined  = None   # (filename, elapsed, path) or None
    exported_dwfx_combined = None   # (filename, elapsed, path) or None
    exported_dwf_combined  = None   # (filename, elapsed, path) or None
    failed        = []   # list of {sheet, format, error, elapsed}
    _pdf_paths_to_compress = []   # collected during loop, batch-compressed after

    sheets_for_batch = [row["sheet"] for row in preview_rows]

    # Batch-export state: {"matched": {sheet: temp_filepath} or None, "tmp_dir": str or None}.
    # "matched" stays None whenever batching wasn't attempted OR was rejected
    # (ambiguous match) — either way the per-sheet loop below transparently
    # falls back to calling export_dwg/export_dxf/export_dwfx per sheet, so
    # a failed batch never blocks the export, it just loses the speed gain.
    _pdf_batch  = {"matched": None, "tmp_dir": None, "elapsed": 0.0}
    _dwg_batch  = {"matched": None, "tmp_dir": None, "elapsed": 0.0}
    _dxf_batch  = {"matched": None, "tmp_dir": None, "elapsed": 0.0}
    _dwfx_batch = {"matched": None, "tmp_dir": None, "elapsed": 0.0}
    _dwf_batch  = {"matched": None, "tmp_dir": None, "elapsed": 0.0}

    total      = (len(preview_rows)
                  + (1 if do_pdf_combined else 0)
                  + (1 if do_dwfx_combined else 0)
                  + (1 if do_dwf_combined else 0)
                  + (1 if do_pdf else 0)
                  + (1 if do_dwg else 0)
                  + (1 if do_dxf else 0)
                  + (1 if do_dwfx else 0)
                  + (1 if do_dwf else 0))
    session_t0 = time.time()

    with forms.ProgressBar(title="Exporting {value} of {max_value}") as pb:
        progress_count = 0

        # ── Batch pre-export: ONE doc.Export() call per format for ALL
        # sheets at once, instead of one call per sheet — each call carries
        # several seconds of fixed Revit-side overhead regardless of sheet
        # complexity, so this is the single biggest lever on total export
        # time. See _match_batch_outputs for the safety contract: a batch
        # that can't be unambiguously matched back to sheets is rejected
        # outright (matched stays None) and the per-sheet loop below simply
        # calls the proven per-sheet function instead — never a silent
        # mis-attribution risk.
        if do_pdf:
            progress_count += 1
            pb.update_progress(progress_count, total)
            _t0 = time.time()
            matched, tmp_dir, _err = export_pdf_batch(sheets_for_batch, _pdf_settings)
            _pdf_batch["matched"]  = matched
            _pdf_batch["tmp_dir"]  = tmp_dir
            _pdf_batch["elapsed"]  = time.time() - _t0

        if do_dwg:
            progress_count += 1
            pb.update_progress(progress_count, total)
            _t0 = time.time()
            matched, tmp_dir, _err = export_dwg_batch(sheets_for_batch, dwg_opts)
            _dwg_batch["matched"]  = matched
            _dwg_batch["tmp_dir"]  = tmp_dir
            _dwg_batch["elapsed"]  = time.time() - _t0

        if do_dxf:
            progress_count += 1
            pb.update_progress(progress_count, total)
            _t0 = time.time()
            matched, tmp_dir, _err = export_dxf_batch(sheets_for_batch, dxf_opts)
            _dxf_batch["matched"]  = matched
            _dxf_batch["tmp_dir"]  = tmp_dir
            _dxf_batch["elapsed"]  = time.time() - _t0

        if do_dwfx:
            progress_count += 1
            pb.update_progress(progress_count, total)
            _t0 = time.time()
            matched, tmp_dir, _err = export_dwfx_batch(sheets_for_batch, dwfx_quality)
            _dwfx_batch["matched"] = matched
            _dwfx_batch["tmp_dir"] = tmp_dir
            _dwfx_batch["elapsed"] = time.time() - _t0

        if do_dwf:
            progress_count += 1
            pb.update_progress(progress_count, total)
            _t0 = time.time()
            matched, tmp_dir, _err = export_dwf_batch(sheets_for_batch, dwf_quality)
            _dwf_batch["matched"] = matched
            _dwf_batch["tmp_dir"] = tmp_dir
            _dwf_batch["elapsed"] = time.time() - _t0

        # ── Combined PDF: one export call for ALL sheets ──────────────────────
        if do_pdf_combined:
            progress_count += 1
            pb.update_progress(progress_count, total)

            combo_name = sanitise(doc.Title) or "Combined_Sheets"
            # Combined PDF contains sheets from multiple Sheet Collections —
            # it cannot live inside a single collection subfolder.
            # Always goes to the root PDF folder regardless of Folder Structure setting.
            combo_folder = os.path.join(output_folder, "PDF")
            if not os.path.exists(combo_folder):
                os.makedirs(combo_folder)

            sheets_in_order = [row["sheet"] for row in preview_rows]
            result, elapsed = export_pdf_combined(
                sheets_in_order, combo_name, combo_folder, _pdf_settings
            )
            if result is True:
                _combo_dest = os.path.join(combo_folder, combo_name + ".pdf")
                if do_compress and _pdf24_doctool():
                    _pdf_paths_to_compress.append(_combo_dest)
                exported_pdf_combined = (combo_name, elapsed, _combo_dest)
            else:
                failed.append({
                    "sheet":   "ALL SHEETS (combined)",
                    "format":  "PDF Merge",
                    "error":   result,
                    "elapsed": elapsed,
                })

        # ── Combined DWFx: one export call, all sheets merged via ViewSet ──
        if do_dwfx_combined:
            progress_count += 1
            pb.update_progress(progress_count, total)

            dwfx_combo_name = sanitise(doc.Title) or "Combined_Sheets"
            # Same rationale as PDF Merge — spans multiple Sheet
            # Collections, so it always goes to the root DWFx folder
            # regardless of the Folder Structure setting.
            dwfx_combo_folder = os.path.join(output_folder, "DWFx")
            if not os.path.exists(dwfx_combo_folder):
                os.makedirs(dwfx_combo_folder)

            sheets_in_order = [row["sheet"] for row in preview_rows]
            result, elapsed = export_dwfx_combined(
                sheets_in_order, dwfx_combo_name, dwfx_combo_folder, dwfx_opts
            )
            if result is True:
                _dwfx_combo_dest = os.path.join(dwfx_combo_folder, dwfx_combo_name + ".dwfx")
                exported_dwfx_combined = (dwfx_combo_name, elapsed, _dwfx_combo_dest)
            else:
                failed.append({
                    "sheet":   "ALL SHEETS (combined)",
                    "format":  "DWFx Merge",
                    "error":   result,
                    "elapsed": elapsed,
                })

        # ── Combined DWF: one export call, all sheets merged via ViewSet ───
        if do_dwf_combined:
            progress_count += 1
            pb.update_progress(progress_count, total)

            dwf_combo_name = sanitise(doc.Title) or "Combined_Sheets"
            # Same rationale as PDF Merge / DWFx Merge — spans multiple Sheet
            # Collections, so it always goes to the root DWF folder
            # regardless of the Folder Structure setting.
            dwf_combo_folder = os.path.join(output_folder, "DWF")
            if not os.path.exists(dwf_combo_folder):
                os.makedirs(dwf_combo_folder)

            sheets_in_order = [row["sheet"] for row in preview_rows]
            result, elapsed = export_dwf_combined(
                sheets_in_order, dwf_combo_name, dwf_combo_folder, dwf_opts
            )
            if result is True:
                _dwf_combo_dest = os.path.join(dwf_combo_folder, dwf_combo_name + ".dwf")
                exported_dwf_combined = (dwf_combo_name, elapsed, _dwf_combo_dest)
            else:
                failed.append({
                    "sheet":   "ALL SHEETS (combined)",
                    "format":  "DWF Merge",
                    "error":   result,
                    "elapsed": elapsed,
                })

        # ── Per-sheet PDF (skipped when combined mode active) + DWG ───────────
        for count, row in enumerate(preview_rows, 1):
            progress_count += 1
            pb.update_progress(progress_count, total)

            sheet    = row["sheet"]
            filename = row["filename"]

            if not filename:
                filename = sanitise(sheet.SheetNumber) or "Sheet_{}".format(count)

            if do_pdf:
                pdf_folder = get_output_path(sheet, output_folder, "PDF", project_has_collections, folder_mode)
                if _pdf_batch["matched"] is not None and _eid_int(sheet.Id) in _pdf_batch["matched"]:
                    # Already exported in the batch call — just move the
                    # pre-matched temp file into place.
                    _t0 = time.time()
                    _src = _pdf_batch["matched"][_eid_int(sheet.Id)]
                    _dest = os.path.join(pdf_folder, filename + ".pdf")
                    try:
                        if os.path.isfile(_dest):
                            os.remove(_dest)
                        shutil.move(_src, _dest)
                        result = True
                    except Exception as e:
                        result = "EXCEPTION (batch move): " + str(e)
                    elapsed = (_pdf_batch["elapsed"] / len(sheets_for_batch)) + (time.time() - _t0)
                else:
                    result, elapsed = export_pdf(sheet, filename, pdf_folder, _pdf_settings)
                if result is True:
                    _pdf_dest = os.path.join(pdf_folder, filename + ".pdf")
                    if do_compress and _pdf24_doctool():
                        _pdf_paths_to_compress.append(_pdf_dest)
                    exported_pdf.append((filename, elapsed, _pdf_dest))
                else:
                    failed.append({
                        "sheet":   sheet.SheetNumber,
                        "format":  "PDF",
                        "error":   result,
                        "elapsed": elapsed,
                    })

            if do_dwg:
                dwg_folder = get_output_path(sheet, output_folder, "DWG", project_has_collections, folder_mode)
                if _dwg_batch["matched"] is not None and _eid_int(sheet.Id) in _dwg_batch["matched"]:
                    # Already exported in the batch call above — just move
                    # the pre-matched temp file into place. Per-sheet elapsed
                    # is the batch's total divided evenly across sheets (an
                    # approximation for the summary/report — real cost was
                    # already spent once, upfront, for every sheet together).
                    _t0 = time.time()
                    _src = _dwg_batch["matched"][_eid_int(sheet.Id)]
                    _dest = os.path.join(dwg_folder, filename + ".dwg")
                    try:
                        if os.path.isfile(_dest):
                            os.remove(_dest)
                        shutil.move(_src, _dest)
                        result = True
                    except Exception as e:
                        result = "EXCEPTION (batch move): " + str(e)
                    elapsed = (_dwg_batch["elapsed"] / len(sheets_for_batch)) + (time.time() - _t0)
                else:
                    result, elapsed = export_dwg(sheet, filename, dwg_folder, dwg_opts)
                if result is True:
                    _dwg_dest = os.path.join(dwg_folder, filename + ".dwg")
                    exported_dwg.append((filename, elapsed, _dwg_dest))
                else:
                    failed.append({
                        "sheet":   sheet.SheetNumber,
                        "format":  "DWG",
                        "error":   result,
                        "elapsed": elapsed,
                    })

            if do_dxf:
                dxf_folder = get_output_path(sheet, output_folder, "DXF", project_has_collections, folder_mode)
                if _dxf_batch["matched"] is not None and _eid_int(sheet.Id) in _dxf_batch["matched"]:
                    _t0 = time.time()
                    _src = _dxf_batch["matched"][_eid_int(sheet.Id)]
                    _dest = os.path.join(dxf_folder, filename + ".dxf")
                    try:
                        if os.path.isfile(_dest):
                            os.remove(_dest)
                        shutil.move(_src, _dest)
                        result = True
                    except Exception as e:
                        result = "EXCEPTION (batch move): " + str(e)
                    elapsed = (_dxf_batch["elapsed"] / len(sheets_for_batch)) + (time.time() - _t0)
                else:
                    result, elapsed = export_dxf(sheet, filename, dxf_folder, dxf_opts)
                if result is True:
                    _dxf_dest = os.path.join(dxf_folder, filename + ".dxf")
                    exported_dxf.append((filename, elapsed, _dxf_dest))
                else:
                    failed.append({
                        "sheet":   sheet.SheetNumber,
                        "format":  "DXF",
                        "error":   result,
                        "elapsed": elapsed,
                    })

            if do_dwfx:
                dwfx_folder = get_output_path(sheet, output_folder, "DWFx", project_has_collections, folder_mode)
                if _dwfx_batch["matched"] is not None and _eid_int(sheet.Id) in _dwfx_batch["matched"]:
                    _t0 = time.time()
                    _src = _dwfx_batch["matched"][_eid_int(sheet.Id)]
                    _dest = os.path.join(dwfx_folder, filename + ".dwfx")
                    try:
                        if os.path.isfile(_dest):
                            os.remove(_dest)
                        shutil.move(_src, _dest)
                        result = True
                    except Exception as e:
                        result = "EXCEPTION (batch move): " + str(e)
                    elapsed = (_dwfx_batch["elapsed"] / len(sheets_for_batch)) + (time.time() - _t0)
                else:
                    result, elapsed = export_dwfx(sheet, filename, dwfx_folder, dwfx_opts)
                if result is True:
                    _dwfx_dest = os.path.join(dwfx_folder, filename + ".dwfx")
                    exported_dwfx.append((filename, elapsed, _dwfx_dest))
                else:
                    failed.append({
                        "sheet":   sheet.SheetNumber,
                        "format":  "DWFx",
                        "error":   result,
                        "elapsed": elapsed,
                    })

            if do_dwf:
                dwf_folder = get_output_path(sheet, output_folder, "DWF", project_has_collections, folder_mode)
                if _dwf_batch["matched"] is not None and _eid_int(sheet.Id) in _dwf_batch["matched"]:
                    _t0 = time.time()
                    _src = _dwf_batch["matched"][_eid_int(sheet.Id)]
                    _dest = os.path.join(dwf_folder, filename + ".dwf")
                    try:
                        if os.path.isfile(_dest):
                            os.remove(_dest)
                        shutil.move(_src, _dest)
                        result = True
                    except Exception as e:
                        result = "EXCEPTION (batch move): " + str(e)
                    elapsed = (_dwf_batch["elapsed"] / len(sheets_for_batch)) + (time.time() - _t0)
                else:
                    result, elapsed = export_dwf(sheet, filename, dwf_folder, dwf_opts)
                if result is True:
                    _dwf_dest = os.path.join(dwf_folder, filename + ".dwf")
                    exported_dwf.append((filename, elapsed, _dwf_dest))
                else:
                    failed.append({
                        "sheet":   sheet.SheetNumber,
                        "format":  "DWF",
                        "error":   result,
                        "elapsed": elapsed,
                    })

    # Queue batch temp directories for deferred cleanup (flushed at session end).
    for _bd in (_pdf_batch, _dwg_batch, _dxf_batch, _dwfx_batch, _dwf_batch):
        _queue_cleanup(_bd.get("tmp_dir"))

    # ── Batch PDF compression: one pdf24-DocTool.exe call for ALL PDFs ────
    # Replaces per-sheet compression (N subprocess launches → 1). Each launch
    # carries ~2-5s of fixed Ghostscript init overhead, so this saves
    # (N-1) x that. Falls back to per-file on any error.
    if _pdf_paths_to_compress:
        _bc_result, _bc_elapsed = compress_pdf_batch(
            _pdf_paths_to_compress, compress_profile)
        if _bc_result is not True:
            # Batch failed — fall back to per-file compression so no PDF
            # is left uncompressed. This is slower but matches old behaviour.
            _per_file_fails = 0
            for _ppath in _pdf_paths_to_compress:
                if os.path.isfile(_ppath):
                    _pf_result, _pf_elapsed = compress_pdf(_ppath, compress_profile)
                    if _pf_result is not True:
                        _per_file_fails += 1
            if _per_file_fails > 0:
                failed.append({
                    "sheet": "BATCH",
                    "format": "PDF Compress",
                    "error": "batch failed ({}), {} of {} per-file fallbacks also failed".format(
                        _bc_result, _per_file_fails, len(_pdf_paths_to_compress)),
                    "elapsed": _bc_elapsed,
                })

    session_elapsed = time.time() - session_t0

    # ---------------------------------------------------------------------------
    # Step 8b: Export selected views (if any)
    # Views go into a _Views_<ModelName> subfolder under the main output folder.
    # Reuses the same format/settings as sheets — PDF/DWG/DXF/DWFx/DWF.
    # ---------------------------------------------------------------------------
    exported_views  = []   # list of (filename, elapsed, path)
    failed_views    = []   # list of {"view": name, "format": fmt, "error": msg}
    _selected_views = _wv.get("selected_views") or []
    _include_views  = _wv.get("include_views", False)

    if _include_views and _selected_views:
        # Root subfolder: _Views_<ModelTitle>
        _model_title = "Model"
        try:
            _mt = doc.Title
            if _mt:
                _model_title = sanitise(_mt)
        except Exception:
            pass
        views_root = os.path.join(output_folder, "_Views_" + _model_title)
        try:
            if not os.path.exists(views_root):
                os.makedirs(views_root)
        except Exception:
            views_root = output_folder   # fallback to root

        # Per-format subfolder helper
        def _fmt_folder(fmt):
            folder = os.path.join(views_root, fmt)
            try:
                if not os.path.exists(folder):
                    os.makedirs(folder)
            except Exception:
                folder = views_root
            return folder

        view_t0 = time.time()
        view_total = len(_selected_views)

        # Build view-specific DWG options (may differ from sheet DWG version)
        _view_dwg_opts = get_dwg_options() if "DWG" in view_formats else None
        if _view_dwg_opts:
            _fallback_ver = list(_DWG_VERSION_MAP.values())[0] if _DWG_VERSION_MAP else ACADVersion.R2018
            _safe_set(_view_dwg_opts, "FileVersion",
                      _DWG_VERSION_MAP.get(view_dwg_version, _fallback_ver))

        with forms.ProgressBar(
                title="Kidzink - Exporting views {value} of {max_value}") as vpb:
            for vcount, _vw in enumerate(_selected_views, 1):
                vpb.update_progress(vcount, view_total)
                _vname = sanitise(_vw.Name) or "View_%s" % _eid_int(_vw.Id)

                for _vfmt in view_formats:
                    vt0 = time.time()
                    _vfmt_folder = _fmt_folder(_vfmt)
                    try:
                        if _vfmt == "DWG":
                            _vr, _ve = export_dwg(
                                _vw, _vname, _vfmt_folder, _view_dwg_opts)
                        elif _vfmt == "PDF":
                            _vr, _ve = export_pdf(
                                _vw, _vname, _vfmt_folder, _pdf_settings)
                        elif _vfmt == "PNG":
                            _vr, _ve = export_view_raster(
                                _vw, _vname, _vfmt_folder,
                                view_resolution, ImageFileType.PNG)
                        elif _vfmt == "JPEG":
                            _vr, _ve = export_view_raster(
                                _vw, _vname, _vfmt_folder,
                                view_resolution, ImageFileType.JPEGLossless)
                        else:
                            continue

                        _ext_map = {"DWG": "dwg", "PDF": "pdf",
                                    "PNG": "png", "JPEG": "jpg"}
                        if _vr is True:
                            _vpath = os.path.join(_vfmt_folder,
                                                   _vname + "." + _ext_map.get(_vfmt, _vfmt.lower()))
                            exported_views.append((_vname, _ve, _vpath))
                        else:
                            failed_views.append({"view": _vw.Name, "format": _vfmt,
                                                 "error": str(_vr)})
                    except Exception as _vex:
                        failed_views.append({"view": _vw.Name, "format": _vfmt,
                                             "error": str(_vex)})

        view_elapsed = time.time() - view_t0
        session_elapsed += view_elapsed   # include in total session time

    # ---------------------------------------------------------------------------
    # Step 9: Auto-open output folder (summary removed - HTML report covers it)
    # ---------------------------------------------------------------------------
    try:
        subprocess.Popen('explorer "' + output_folder + '"')
    except Exception:
        pass


    # ---------------------------------------------------------------------------
    # HTML Report — saved in the MAIN output folder (root, not PDF/DWG subfolders)
    # Skipped entirely when "Include HTML report after export" is unchecked in
    # Settings — the export itself still runs, just no report file is written.
    # ---------------------------------------------------------------------------
    if _wv.get("include_report", True):
        _now         = datetime.datetime.now()
        _report_name = _now.strftime("%y%m%d.%H%M") + "_SheetExportReport.html"
        _report_path = os.path.join(output_folder, _report_name)

        _rows_parts = []
        _row_num   = 0

        if do_pdf_combined and exported_pdf_combined:
            _row_num += 1
            _combo_name, _combo_elapsed, _combo_path = exported_pdf_combined
            _rows_parts.append(
                '<tr><td>' + str(_row_num) + '</td>'
                '<td>' + _esc(_combo_name) + '.pdf</td>'
                '<td>PDF Merge (' + str(len(preview_rows)) + ' sheets)</td>'
                '<td>' + fmt_size(_combo_path) + '</td>'
                '<td>' + fmt_time(_combo_elapsed) + '</td></tr>'
            )

        if do_dwfx_combined and exported_dwfx_combined:
            _row_num += 1
            _dwfx_combo_name, _dwfx_combo_elapsed, _dwfx_combo_path = exported_dwfx_combined
            _rows_parts.append(
                '<tr><td>' + str(_row_num) + '</td>'
                '<td>' + _esc(_dwfx_combo_name) + '.dwfx</td>'
                '<td>DWFx Merge (' + str(len(preview_rows)) + ' sheets)</td>'
                '<td>' + fmt_size(_dwfx_combo_path) + '</td>'
                '<td>' + fmt_time(_dwfx_combo_elapsed) + '</td></tr>'
            )

        if do_dwf_combined and exported_dwf_combined:
            _row_num += 1
            _dwf_combo_name, _dwf_combo_elapsed, _dwf_combo_path = exported_dwf_combined
            _rows_parts.append(
                '<tr><td>' + str(_row_num) + '</td>'
                '<td>' + _esc(_dwf_combo_name) + '.dwf</td>'
                '<td>DWF Merge (' + str(len(preview_rows)) + ' sheets)</td>'
                '<td>' + fmt_size(_dwf_combo_path) + '</td>'
                '<td>' + fmt_time(_dwf_combo_elapsed) + '</td></tr>'
            )

        if do_pdf:
            for f, e, p in exported_pdf:
                _row_num += 1
                _rows_parts.append(
                    '<tr><td>' + str(_row_num) + '</td>'
                    '<td>' + _esc(f) + '.pdf</td><td>PDF</td>'
                    '<td>' + fmt_size(p) + '</td>'
                    '<td>' + fmt_time(e) + '</td></tr>'
                )

        if do_dwg:
            for f, e, p in exported_dwg:
                _row_num += 1
                _rows_parts.append(
                    '<tr><td>' + str(_row_num) + '</td>'
                    '<td>' + _esc(f) + '.dwg</td><td>DWG</td>'
                    '<td>' + fmt_size(p) + '</td>'
                    '<td>' + fmt_time(e) + '</td></tr>'
                )

        if do_dxf:
            for f, e, p in exported_dxf:
                _row_num += 1
                _rows_parts.append(
                    '<tr><td>' + str(_row_num) + '</td>'
                    '<td>' + _esc(f) + '.dxf</td><td>DXF</td>'
                    '<td>' + fmt_size(p) + '</td>'
                    '<td>' + fmt_time(e) + '</td></tr>'
                )

        if do_dwfx:
            for f, e, p in exported_dwfx:
                _row_num += 1
                _rows_parts.append(
                    '<tr><td>' + str(_row_num) + '</td>'
                    '<td>' + _esc(f) + '.dwfx</td><td>DWFx</td>'
                    '<td>' + fmt_size(p) + '</td>'
                    '<td>' + fmt_time(e) + '</td></tr>'
                )

        if do_dwf:
            for f, e, p in exported_dwf:
                _row_num += 1
                _rows_parts.append(
                    '<tr><td>' + str(_row_num) + '</td>'
                    '<td>' + _esc(f) + '.dwf</td><td>DWF</td>'
                    '<td>' + fmt_size(p) + '</td>'
                    '<td>' + fmt_time(e) + '</td></tr>'
                )

        for _f in failed:
            # 5-column layout to match the table header
            # (# | Filename | Type | Size | Time): the cross goes in #, the
            # sheet under Filename, the format under Type, and the error text
            # spans the remaining Size+Time columns via colspan.
            _rows_parts.append(
                '<tr style="color:#C2342B;"><td>\u274c</td>'
                '<td>' + _esc(_f["sheet"]) + '</td>'
                '<td>' + _esc(_f["format"]) + '</td>'
                '<td colspan="2">' + _esc(_f["error"]) + '</td></tr>'
            )

        _total_exported = (
            (1 if (do_pdf_combined and exported_pdf_combined) else 0)
            + (1 if (do_dwfx_combined and exported_dwfx_combined) else 0)
            + (1 if (do_dwf_combined and exported_dwf_combined) else 0)
            + (len(exported_pdf) if do_pdf else 0)
            + (len(exported_dwg) if do_dwg else 0)
            + (len(exported_dxf) if do_dxf else 0)
            + (len(exported_dwfx) if do_dwfx else 0)
            + (len(exported_dwf) if do_dwf else 0)
        )

        _html = (
            "<!DOCTYPE html><html><head><meta charset=\"UTF-8\">"
            "<title>Kidzink Sheet Export Report</title>"
            "<style>"
            "body{font-family:Arial,sans-serif;margin:32px;color:#16242E;background:#fff;}"
            "h1{color:#E43C2F;font-size:20px;border-bottom:3px solid #E43C2F;padding-bottom:8px;}"
            "h2{color:#16242E;font-size:14px;margin-top:24px;}"
            "table{border-collapse:collapse;width:100%;font-size:13px;}"
            "th{background:#16242E;color:#fff;padding:7px 12px;text-align:left;}"
            "td{padding:6px 12px;border-bottom:1px solid #eee;}"
            ".meta{font-size:12px;color:#888;margin-bottom:20px;}"
            ".footer{font-size:11px;color:#999;margin-top:32px;border-top:1px solid #eee;padding-top:8px;}"
            "</style></head><body>"
            "<h1>Kidzink - K\u00f6da &mdash; Sheet Export Report</h1>"
            "<div class=\"meta\">"
            "<b>Source:</b> " + _esc(selected_name) + " &nbsp;|"
            " <b>Format:</b> " + _esc(export_format_label) + " &nbsp;|"
            " <b>Quality:</b> " + _esc(pdf_quality) + " &nbsp;|"
            " <b>Processing:</b> " + _esc(pdf_processing) + "<br/>"
            " <b>Output:</b> " + _esc(output_folder) + "<br/>"
            " <b>Generated:</b> " + _now.strftime("%Y-%m-%d %H:%M") +
            "</div>"
            "<h2>Exported &mdash; " + str(_total_exported) + " file(s)"
            " &nbsp;|&nbsp; Session time: " + fmt_time(session_elapsed) + "</h2>"
            "<table><tr><th>#</th><th>Filename</th><th>Type</th><th>Size</th><th>Time</th></tr>"
            + "".join(_rows_parts) +
            "</table>"
            "<div class=\"footer\">&copy; 2026 Archie C. Manza</div>"
            "</body></html>"
        )

        try:
            with open(_report_path, "wb") as _rf:
                _rf.write(_html.encode("utf-8"))
        except Exception:
            pass

    # Flush all deferred temp-directory removals in one pass at session end,
    # off the per-sheet critical path.
    _flush_cleanup()

    # Stop auto-dismissing Revit dialogs now that the export is done.
    _unsubscribe_auto_dismiss()


# ---------------------------------------------------------------------------
# Dispatch: interactive immediate export, or headless scheduled run.
# (Interactive scheduling itself already saved a pending-schedule file and
# exited, far above — this only runs for immediate exports and headless runs.)
# ---------------------------------------------------------------------------
if _KIDZINK_HEADLESS_STATE is not None:
    _sched_log("Headless run: executing export now")
    try:
        _run_export(output_folder)
        _sched_log("Headless run: export completed")
    except Exception as _hex:
        _sched_log("Headless run: export failed: %s" % str(_hex))
        try:
            forms.alert(
                "Scheduled export failed:\n%s" % str(_hex),
                title="Scheduled Export Error")
        except Exception:
            pass
    script.exit()
else:
    _run_export(output_folder)
